// STAGED ns.ramOverride REWRITE of progress.js.
//
// Hand-written rather than generated by stage.mjs, because progress.js is the
// one candidate with a REAL ungated path: without Source-File 4 it still reads
// the player, checks TOR and the port programs, and writes /tel/todo.txt so a
// human knows what to click. That path has to keep working at a small
// allocation, so this file raises to one of TWO ceilings instead of returning.
//
// The original `main` body is preserved as `act(ns, canJoin)` with exactly ONE
// substantive change, described under "the probe" below.
//
// The `player.currentWork` / `player.focus` defects recorded in
// docs/game-knowledge.md §1 ARE now fixed, because wiring this file into
// watchdog.js made them live: getPlayer() returns neither field
// (NetscriptFunctions.ts:1371-1389), so `!work` was always true and every
// launch restarted focused faction work, and the refocus branch was
// unreachable. Under a supervisor that relaunches on an interval, that is a
// script stealing the UI every few minutes. Both now read through
// ns.singularity.getCurrentWork / isFocused. `player.factionInvitations` is
// still absent from getPlayer(), but the acting path already sources
// invitations from sing.checkFactionInvitations(); only the SF4-less advisory
// fallback reads the missing field, and it degrades to "no invitations".
//
// ---------------------------------------------------------------------------
// RAMOVERRIDE 2.6GB — excludes: every ns.singularity.* call in this file —
// getOwnedAugmentations / purchaseAugmentation / installAugmentations /
// getAugmentationsFromFaction (5GB each at base price, 80GB each at the 16x
// SF4.1 rate), workForFaction / checkFactionInvitations / joinFaction (3/48GB),
// getAugmentationRepReq / getAugmentationPrice (2.5/40GB), purchaseTor /
// purchaseProgram (2/32GB), getFactionRep (1/16GB) and setFocus (0.1/1.6GB) —
// and also ns.getPlayer, ns.hasTorRouter, ns.fileExists and
// ns.getServerMoneyAvailable, which the advisory path does use but only AFTER
// the allocation has been raised to RAISE_CEILING(0).
//
// 2.6 = RamCostConstants.Base (1.6) + ns.getResetInfo (1.0): everything called
// before the capability decision. sfgate.js is pure and status.js touches only
// ns.write (0GB).
//
// TWO ceilings, both raised through ramgrow.js before any of the excluded calls:
//   RAISE_CEILING(0)     the advisory path — every non-singularity call in the
//                        file, and nothing else. This is what makes a BitNode
//                        with no SF4 able to run progress.js at all; the shipped
//                        file costs 627.95GB there and simply cannot be started.
//   RAISE_CEILING(mult)  the acting path — the file's full static price at this
//                        save's Singularity RAM multiplier (sfgate.js:71-77).
//
// THE PROBE. The shipped file decides capability by CALLING a singularity
// function inside a try/catch (`capable(ns, () => sing.getOwnedAugmentations(false))`).
// That cannot survive an override: APIWrapper.ts:80 charges the call's RAM
// BEFORE the body runs, so the probe alone costs 5GB (80GB at SF4.1) and
// NetscriptHelpers.tsx:523 calls killWorkerScript before it throws — the catch
// runs but the script is already dead. The probe is therefore replaced by
// `canUseSingularity(info)`, which is the SAME predicate the game itself uses:
// checkSingularityAccess (NetscriptHelpers.tsx:438-446) is a bare
// `canAccessBitNodeFeature(4)`, and sfgate.js:63 is that rule. Invariant SF3 —
// the gate is not open-coded here.
//
// Registered in tools/sim/bncheck.mjs STRUCTURAL. Asserted by
// tools/test/ramoverride.test.mjs [R1..R5].
// ---------------------------------------------------------------------------
// Drives progression: joins factions, works for reputation, buys programs and
// augmentations, and installs — automatically where the game allows it, and by
// telling a human exactly what to click where it does not.
//
//   run progress.js              act where possible, report the rest
//   run progress.js --dry        decide and report, change nothing
//   run progress.js --no-install never install, even when the trigger is met
//
// ---------------------------------------------------------------------------
// Why it is written this way
//
// Almost everything a player does outside a terminal — joining a faction,
// working for reputation, buying a program, upgrading home RAM, purchasing an
// augmentation, installing — lives behind `ns.singularity.*`, which requires
// Source-File 4. In a BitNode where SF4 is absent those actions cannot be
// scripted at all, and the progression stalls silently: the fleet keeps
// earning, the level keeps climbing, and reputation sits at zero because
// nobody clicked anything.
//
// So this script does not assume either world. It probes for each capability
// once, uses what is available, and writes what it could not do to
// /tel/todo.txt so the gap is visible instead of silent. The same file works
// unchanged on a fresh BitNode 1 with nothing and on a late run with every
// Source-File — it simply does more of the work itself as more becomes
// available.
// ---------------------------------------------------------------------------

const STATUS = '/tel/progress.txt'
const TODO = '/tel/todo.txt'
const GATE = '/tel/installgate.txt'
const SCHEDULE = '/tel/factionplan.txt'

/**
 * w0r1d_d43m0n's hacking requirement BEFORE the BitNode scales it.
 *
 * 3000 in the server table (Server/data/servers.ts, the WorldDaemon entry),
 * multiplied at BitNode entry by that node's WorldDaemonDifficulty
 * (ServerHelpers.ts:422-423). So the exit is 9000 in BitNode 4, 3000 in
 * BitNode 1, 4500 in BitNode 5, 15000 in BitNode 2.
 *
 * installgate.js defaults its `target` to 9000, which was correct for exactly
 * one BitNode. The live server is authoritative but is not addressable until
 * The Red Pill is installed (Prestige.ts:174-181), so the verified table is
 * what a run can read from its first pass.
 */
const WD_BASE_HACKING = 3000

import { canUseSingularity, singularityRamMultiplier, totalSfLevels, canUseGang } from 'sfgate.js'
import { GANG_FACTIONS } from 'gangplan.js'
// The whole faction space as data — see factions.js and [BC9].
import { ALL_FACTIONS } from 'factions.js'
import { reporter } from 'status.js'
import { raiseRam } from 'ramgrow.js'
import {
  shouldInstall,
  progressFactor,
  multiplierNeeded,
  RATE_CHANNELS,
  expForSkill,
  scoreFutures,
  discountFutures,
  carryPredictions,
} from 'installgate.js'
import { planSchedule, bestCompatibleSet, holdCandidates, logValue } from 'factionplan.js'
import { joinWait, timeToMeet } from 'joinplan.js'
// Pure: the expected contract stream, which is NOT script income and so is
// invisible to getTotalScriptIncome (contractplan.js has the derivation).
import { contractIncome } from 'contractplan.js'
// Pure: the stock-market entry as an investment decision (stockplan.js).
import { entryCost as stockEntryCost, verdict as stockVerdict } from 'stockplan.js'
import { MEGACORPS, SOFTWARE_TRACK, companyRepPerSec, hoursToCompanyRep } from 'companyplan.js'
import { bitNodeMults } from 'bitNodeMultipliers.js'

/** GymType uses skill SHORT CODES (Work/Enums.ts:17-22) and gymWorkout's
 *  nsGetMember is strict — "strength" throws, "str" works. */
const GYM_CLASS = { strength: 'str', defense: 'def', dexterity: 'dex', agility: 'agi' }
import { STORY_SERVERS } from 'storyservers.js'
import { repModel, incomeModel, estimateBaseRepPerSec } from 'trajectory.js'
import { deriveWeights, pathGainWeight, augValue, bindingGate, TERMINAL_AUG, moneyLn } from 'objective.js'
// Pure: the best money crime at current stats, for the work-slot comparison.
import { bestCrimeFor } from 'bodyplan.js'
// Pure trajectory arithmetic, no ns surface: free to import.
import { bestExitPolicy, cycleStats } from 'exitplan.js'
import { measureFromLedger, installRecord, ledgerScores, achievableRate } from 'scorecard.js'
import { addRepToFavor, donationUplift, repLadder, favorNeededToDonate, donationForRep, nfgLevelsByDonation, repToCross } from 'favor.js'
import { planPurchases, NFG, isSoa, BASE_PRICE_MULT } from 'augplan.js'

/** This file's static price as a function of the Singularity RAM multiplier.
 *  RAISE_CEILING(0) is every non-singularity call in the file; the second term
 *  is the ns.singularity surface at base price. Both measured with the game's
 *  own calculator; re-checked on every run by ramoverride.test.mjs [R5], which
 *  fails if the ceiling does not reach the full static price in any regime. */
// 39.1 -> 39.7: reading the work state properly added ns.singularity
// getCurrentWork (0.5 base) and isFocused (0.1 base), both scaled by the
// Singularity multiplier. Asserted against the game's own calculator by
// tools/test/ramoverride.test.mjs [R1..R5] — if this number drifts from the
// file's real static price the raise is short, and a short raise is SILENTLY
// denied (NetscriptFunctions.ts:1210-1214 returns the old allocation), so the
// test is the only thing standing between a wrong constant and a script that
// dies mid-run for no visible reason.
// 39.7 -> 49.7, and TWO separate reasons, only one of which is this change.
//
// (1) +5.0 for ns.singularity.getAugmentationPrereq (RamCostGenerator.ts:205,
//     SingularityFn3 = 5GB base, scaled by the SF4 RAM multiplier). Without it
//     the planner cannot see prerequisites, and descending PRICE order puts
//     "Cranial Signal Processors - Gen V" before Gen I, so the purchase is
//     rejected (FactionHelpers.tsx:88-95) and purchaseAugmentation returns false
//     with nothing reporting it.
//
// (2) +5.0 THAT WAS ALREADY MISSING. The shipped constant is 39.7 and the
//     shipped file's real static price is 44.7 per multiplier unit — measured
//     at 48.05GB in BitNode 4 and 718.55GB at SF4.1 by BOTH tools/test/ram.mjs
//     (priceOverlay, the game's own calculateRamUsage) and
//     tools/staging/ramcheck.mjs, which agree exactly. So the deployed ceiling
//     is 43.05 against a 48.05 requirement: 5GB short in BN4 and 80GB short at
//     SF4.1. A short raise is SILENTLY denied (NetscriptFunctions.ts:1210-1214
//     returns the old allocation) and the script then dies mid-run with no
//     signal. It is dormant today only because this save has no Source-File 4,
//     so canJoin is false and the advisory ceiling RAISE_CEILING(0) = 3.35 is
//     the one used — and 3.35 is correct. It breaks the day SF4 arrives.
//
//     tools/test/ramoverride.test.mjs [R5] does not catch it because its subject
//     is tools/staging/ramoverride/progress.js, which is stale: that copy still
//     says 39.1 and lacks getAugmentationStats, getCurrentWork and isFocused —
//     exactly the 5.6GB of calls the root file gained. R5 reports "progress.js
//     BN4 full 42.45GB" and passes, while the file that actually runs costs
//     48.05GB. A test checking a copy of the thing it guards.
//
// 49.7 is MEASURED, not arithmetic: priceOverlay puts this file at 53.05GB in
// BN4 (= 3.35 + 49.7) and 798.55GB at SF4.1 (= 3.35 + 49.7*16).
// 3.35 -> 3.45 on the FLAT term: the forward projection added
// ns.getTotalScriptIncome (0.10GB, not Singularity-scaled, so it lands on the
// constant and not on `mult`). Re-measured with the game's own calculator
// against this file with its override stripped: 53.15GB in BN4, 798.65GB at
// SF4.1. Measure, never derive — a 5GB error from doing this by arithmetic is
// already in this file's history.
// 49.7 -> 50.7: choosing the faction nearest the donation threshold added
// ns.singularity.getFactionFavor (1GB base, Singularity-scaled). Re-measured
// against the game's own calculator with the override stripped: 54.15GB in BN4,
// 814.65GB at SF4.1. Measure, never derive — a 5GB error from doing this by
// arithmetic is already in this file's history.
// 50.7 -> 53.7: pricing city factions added ns.singularity.getFactionEnemies
// (3GB base, Singularity-scaled). Re-measured with the game's own calculator
// against this file with its override stripped: 57.15GB in BN4, 862.65GB at
// SF4.1. Measure, never derive — a 5GB error from arithmetic is already in this
// file's history, and a short raise is denied SILENTLY.
// 56.8 -> 63.8: the megacorp path added ns.singularity.getCompanyRep (1),
// applyToCompany (3) and workForCompany (3), all scaled by the SF4 multiplier.
// 63.8 -> 64.8: getCompanyFavor (1) — company favour survives installs and
// multiplies later rep gain, so the forecast must read it or it repeats the
// same 22h every life while the true walk shrinks.
// 64.8 -> 68.8: the training step — travelToCity (2) and universityCourse (2),
// fired only when the trajectory model says studying first beats the plain
// stint on total hours.
// 68.8 -> 69.0: getSharePower (0.2) for the unmeasured-rate estimator, so the
// share bonus the game applies to faction work is in the estimate too.
// 69.0 -> 74.0: donateToFaction (5, SingularityFn3) — past 150 favour the
// planner opens rep walls with donations, and the executor pays them.
// Measured by [R5] against the game's own calculator, as every bump before it.
// 74.0 -> 81.0: the body step — gymWorkout (2, SingularityFn1) and
// commitCrime (5, SingularityFn3), the actors for joinplan's combat-stat and
// karma forecasts. 8.85 -> 9.35: ns.hacknet.getTrainingMult (RamCostConstants.
// Hacknet = 0.5), the gym-rate scalar the forecast reads rather than assumes.
// 9.35 -> 9.55: ns.stock.hasWseAccount / hasTixApiAccess / has4SData /
// has4SDataTixApi (0.05 each, RamCostGenerator.ts:126-129) for the stock
// entry pricing; getConstants is 0.
const RAISE_CEILING = (mult) => 9.55 + 81.0 * mult

export async function main(ns) {
  ns.ramOverride(2.6)

  // This reporter covers the paths that would otherwise produce silence.
  const note = reporter(ns, STATUS, {})

  // ns.atExit, added when progress.js entered watchdog.js's WATCHED list
  // (invariant C1: every managed script publishes on return, handled error,
  // throw AND kill).
  //
  // The original note here said an exit hook was deliberately omitted, because
  // act() writes /tel/progress.txt as its last statement and a reporter
  // republishing over it would change the shape readers parse. That reasoning
  // held while nothing supervised this file. It does not hold now: the kill
  // path writes nothing at all, and a managed script that dies silently is
  // indistinguishable from one that is merely between runs — precisely the
  // gap that let "no faction joined" persist for nine hours.
  //
  // The conflict is resolved by making the hook CONDITIONAL rather than
  // unconditional. `finished` is set only after act() has published its own
  // report, so the normal path still leaves act()'s richer shape untouched and
  // the hook fires only on kill, throw, or an install that never returns.
  // ns.atExit is 0GB and runs before teardown (killWorkerScript.ts:64-84), so
  // the write lands. Explicit id so it cannot displace lock.js's 'ui-lock'.
  let finished = false
  ns.atExit(() => {
    if (finished) return
    note.exit('stopped', {
      detail: 'progress.js exited without publishing — killed, threw, or installed augmentations',
    })
  }, 'status')

  const info = ns.getResetInfo()
  const canJoin = canUseSingularity(info)
  const want = canJoin ? RAISE_CEILING(singularityRamMultiplier(info)) : RAISE_CEILING(0)

  if (!(await raiseRam(ns, want, STATUS, canJoin ? 'progress.js acting path' : 'progress.js advisory path'))) {
    // raiseRam ALREADY published, to this same file, a record naming exactly
    // what was wanted and what was granted — and ramgrow.js's own comment says
    // "this line is the only record". So this is a published path, and the exit
    // hook must not fire over it.
    //
    // It did. Live, the first run under SF4.1 wanted 1187.45GB on a 128GB home,
    // ramgrow wrote `ram-raise-denied` with both figures, and the hook replaced
    // it with "exited without publishing — killed, threw, or installed
    // augmentations" — three guesses, none of them what happened, over a
    // diagnosis that was already correct. `finished` meant "act() published"
    // when what the hook actually needs to know is "anything published".
    finished = true

    // AND PUBLISH A ZERO CLAIM, because silence here is a DEADLOCK, not a gap.
    //
    // budget.js's spenders hold back whatever this file says is promised to
    // augmentations, and an unreadable claim blocks the spend rather than
    // reading as zero ([BU2]) — which is right, since a spender that guesses
    // zero would race the augmentation plan for the same dollars.
    //
    // But the file left behind by the PREVIOUS BitNode is unreadable in exactly
    // that way: augClaim refuses a claim whose lastAugReset is not this life's
    // (budget.js:189). So on arriving in a new node, the chain was:
    //
    //   progress.js cannot raise RAM  ->  never rewrites this file
    //     ->  augClaim returns null on the stale one
    //       ->  homeup.js's trigger sees a non-finite hold and refuses
    //         ->  home RAM never grows  ->  progress.js can never raise RAM
    //
    // Observed live in BitNode 1: home sat at 128GB with $2.75b in the bank and
    // `homeup.js | idle: trigger false`, while the only script that could clear
    // the claim was the one waiting on the RAM the claim was blocking.
    //
    // The honest claim is ZERO. A progress.js that cannot raise RAM cannot plan
    // or buy anything, so nothing is promised — and saying so is strictly more
    // accurate than leaving the previous node's plan standing. This is the same
    // shape act() writes when it has no plan, so readers parse one thing.
    ns.write(
      GATE,
      JSON.stringify(
        {
          at: new Date().toISOString(),
          lastAugReset: info?.lastAugReset,
          planned: false,
          pending: [],
          plan: null,
          // joinClaim is NOT optional here, and omitting it rebuilt the very
          // deadlock described above one claimant to the left.
          //
          // augClaim reads `plan: null` + `planned: false` as a known zero, so
          // the record above satisfied it. joinClaim (budget.js) is stricter by
          // design — ONLY a finite number is a claim, because the publisher
          // returns null exactly when it could not read the candidate set, and
          // that case must block rather than license spending. With no
          // joinClaim field at all it returned null, budgetHold went
          // non-finite, and homeup.js reported
          //   "BLOCKED: the augmentation claim ... is unreadable"
          // — naming augClaim, which was in fact answering correctly.
          //
          // Observed live in BitNode 5: home pinned at 512GB with $3.92b in the
          // bank while progress.js needed 1192GB to run, homeup.js never
          // launched once (count: 0), and the message pointed at the wrong
          // claimant the whole time.
          //
          // Zero is the honest value for the same reason the comment above
          // gives: a progress.js that cannot raise RAM cannot join a faction
          // either, so no money is promised to a join.
          joinClaim: 0,
        },
        null,
        2,
      ),
      'w',
    )
    return
  }

  try {
    const r = await act(ns, canJoin, info)
    finished = true
    return r
  } catch (err) {
    // The shipped file has no catch at all, so a throw anywhere in it produced
    // nothing but a dead process. Publish, then rethrow so nothing is hidden.
    note('error', { result: 'error', canJoin, allocation: want, detail: String(err) })
    // Mark published BEFORE rethrowing. The atExit hook fires after this and
    // would otherwise overwrite a report naming the actual exception with the
    // generic "exited without publishing" — turning a precise diagnosis into a
    // vaguer one, which is the opposite of what the hook is for.
    finished = true
    throw err
  }
}


/*
 * REMOVED: `capable(ns, fn)`, the try/catch probe.
 *
 * The shipped file's reasoning was "there is no 'do I have Source-File 4' API
 * that does not itself cost RAM, so the honest test is to call the thing and
 * see whether it throws." Both halves are wrong now:
 *
 *  - ns.getResetInfo() costs 1.0GB and answers it exactly. The game's own gate,
 *    checkSingularityAccess (NetscriptHelpers.tsx:438-446), is a bare
 *    canAccessBitNodeFeature(4), which is sfgate.js:63.
 *  - the probe is FATAL under an ns.ramOverride: APIWrapper.ts:80 charges the
 *    call's RAM before its body runs, and NetscriptHelpers.tsx:523 calls
 *    killWorkerScript(ws) before throwing — so the catch runs in a process that
 *    is already dead. A 5GB (80GB at SF4.1) probe to learn something a 1GB call
 *    already knows.
 *
 * The 'SF may be present at level 1 with some calls gated higher' worry does not
 * apply: every ns.singularity function goes through the same level-free gate.
 */

/** Factions that sell hacking augmentations, best first for our purposes. */
const HACK_FACTIONS = [
  'Daedalus',
  'BitRunners',
  'The Black Hand',
  'NiteSec',
  'CyberSec',
  'Netburners',
]

/** Never join these without a reason: they conflict with other city factions. */
const CITY_FACTIONS = ['Sector-12', 'Aevum', 'Volhaven', 'Chongqing', 'New Tokyo', 'Ishima']

/**
 * The live IPvGO faction-reputation bonus, as a percent.
 *
 * Read from go.js's telemetry rather than ns.go.analysis.getStats, which would
 * add 4GB to this file's static price for a number that is already published.
 * ns.read is 0GB and returns '' for a missing file, so this cannot throw.
 */
function goBonus(ns) {
  try {
    const d = JSON.parse(ns.read('/tel/go.txt') || '{}')
    const v = d?.factionRepBonusPct
    return typeof v === 'number' && isFinite(v) && v >= 0 ? v : 0
  } catch {
    return 0
  }
}

/**
 * Is the faction we are currently working not the one we should be?
 *
 * Deliberately conservative: any doubt (no Singularity, unreadable work, an
 * empty faction list) answers FALSE, i.e. "leave it alone". Switching on a bad
 * read would drop a running grind for nothing, and an unknown must not present
 * as a reason to act.
 */
function wrongFaction(sing, work, factions, canJoin, target) {
  if (!canJoin || !work || work.type !== 'FACTION') return false
  const current = work.factionName
  if (!current || !factions?.length || !target) return false
  return target !== current
}

/**
 * Which joined faction to work when the choice is ours — the measuring
 * fallback's target, and the answer to "an hour here buys what?".
 *
 * Three tiers, and the tiers are the whole idea:
 *
 *  1. A faction that still owes us an augmentation AND cannot be donated to.
 *     Below the donation threshold, work is the ONLY channel that moves
 *     reputation, so an hour here is irreplaceable. Nearest unlock first,
 *     because the augmentation released soonest is the one that starts
 *     compounding soonest.
 *  2. A faction that owes us an augmentation but is past the threshold. Its
 *     reputation is purchasable (donation.ts:8), so work is dominated by
 *     money — but it is not worthless, so it outranks nothing at all.
 *  3. Anything joined. Reached only when no faction has a locked augmentation
 *     left; the work then buys nothing but the rate measurement, which is
 *     itself the reason this function was called.
 *
 * Locked-by-REPUTATION is the test, not merely unowned: an augmentation we
 * can already afford the reputation for is not waiting on work.
 */
function measuringTarget(sing, factions, offers, info) {
  const byQuality = HACK_FACTIONS.find((f) => factions.includes(f)) ?? factions[0]
  let donateNeed = null
  try {
    // Fail-closed on an unknown BitNode: null threshold means nothing counts
    // as donatable, so every faction keeps work as its reputation channel.
    const mult = bitNodeMults(info?.currentNode)?.FavorToDonateToFaction
    donateNeed = typeof mult === 'number' ? favorNeededToDonate(mult) : null
  } catch {
    /* unknown threshold -> nothing is treated as donatable, so work stands */
  }
  let best = null
  for (const f of factions) {
    let gap = Infinity
    for (const o of offers ?? []) {
      if (o.faction !== f || o.name === NFG) continue
      const d = o.repReq - o.factionRep
      if (d > 0 && d < gap) gap = d
    }
    if (!isFinite(gap)) continue
    // Fail-closed on an unreadable favour: an unknown does NOT get to claim
    // "donate instead", which would demote a faction whose reputation we may
    // in fact only be able to work for.
    let donatable = false
    try {
      donatable = donateNeed !== null && sing.getFactionFavor(f) >= donateNeed
    } catch {
      /* unreadable favour -> not donatable -> work is the channel */
    }
    const rank = [donatable ? 1 : 0, gap]
    if (!best || rank[0] < best.rank[0] || (rank[0] === best.rank[0] && rank[1] < best.rank[1])) best = { f, rank }
  }
  return best?.f ?? byQuality
}

/**
 * The faction work schedule, with the reputation rate MEASURED rather than
 * assumed.
 *
 * Ranking is invariant to the base rate — it cancels in every comparison — but
 * the published hours are not, and a schedule that claims "2.1h" while meaning
 * "2.1 arbitrary units" is worse than one that says it does not know. So the
 * rate comes from the previous pass's reputation, persisted alongside the plan,
 * exactly as installgate.js persists its own previous sample.
 *
 * With no previous sample the ranking is still correct and the hours are
 * flagged `estimated`, rather than being presented as measured.
 */
function planFactionWork(ns, sing, factions, offers, info, joinCtx = null) {
  const prior = readJson(ns, SCHEDULE) ?? {}
  const now = Date.now()
  const reps = {}
  const byFaction = new Map()
  for (const f of factions) {
    reps[f] = sing.getFactionRep(f)
    byFaction.set(f, { name: f, rep: reps[f], favor: sing.getFactionFavor(f), augs: [] })
  }
  for (const o of offers) {
    const e = byFaction.get(o.faction)
    if (e) e.augs.push({ name: o.name, repReq: o.repReq, mults: o.mults })
  }

  // Measured rate: reputation gained at the faction we were actually working,
  // divided by elapsed time, with the favour multiplier divided back out so it
  // is a BASE rate the module can re-apply per faction.
  let base = null
  const wasWorking = prior.workingFaction
  if (prior.at && prior.reps && wasWorking && reps[wasWorking] != null && prior.reps[wasWorking] != null) {
    const dt = (now - Date.parse(prior.at)) / 1000
    const dr = reps[wasWorking] - prior.reps[wasWorking]
    const favor = prior.favors?.[wasWorking] ?? 0
    if (dt > 5 && dr > 0) base = dr / dt / (1 + favor / 100)
  }

  // Hacking-exp rate, measured the same way and stored the same place. It is
  // what turns "BitRunners needs hacking 505" into an ETA. A stale-life prior
  // cannot poison it: SCHEDULE carries lastAugReset and the read below guards
  // on it, and exp only rises within a life so a negative delta means the
  // sample is not ours and is refused.
  let expRate = null
  const expNow = joinCtx?.state?.hackingExp
  if (prior.at && typeof prior.hackingExp === 'number' && typeof expNow === 'number' && prior.lastAugReset === info?.lastAugReset) {
    const dt = (now - Date.parse(prior.at)) / 1000
    const de = expNow - prior.hackingExp
    if (dt > 5 && de > 0) expRate = de / dt
  }

  // Company reputation rate, measured exactly like the faction rate: the
  // delta at whichever company actually moved since the prior sample. This is
  // the calibration loop companyplan.js's header promises — its formula prices
  // a company we have never worked, and the measurement REPLACES the formula
  // the moment work starts. Positive deltas only: company rep never decays,
  // so a negative delta means the sample is not from this life.
  const companyReps = joinCtx?.state?.companyCtx?.repByCompany ?? {}
  const measuredCompanyRates = {}
  if (prior.at && prior.companyReps && prior.lastAugReset === info?.lastAugReset) {
    const dt = (now - Date.parse(prior.at)) / 1000
    if (dt > 5) {
      for (const [co, rep] of Object.entries(companyReps)) {
        const dr = rep - (prior.companyReps[co] ?? 0)
        if (dr > 0) measuredCompanyRates[co] = dr / dt
      }
    }
  }
  if (joinCtx?.state?.companyCtx) joinCtx.state.companyCtx.measuredRates = measuredCompanyRates

  // Price the join boundary: forecast each unjoined candidate's wait and enter
  // the priceable ones into the SAME ranking as the joined factions. The
  // unpriceable are surfaced with their blockers — an unknown wait ranks a
  // faction nowhere, and that refusal must be visible, not an absence.
  //
  // PASSIVE and ACTIVE waits enter separately (joinplan.js's header has the
  // model): passive hours are a release time the schedule can fill with other
  // work, active hours are company employment that displaces it.
  const joinForecasts = []
  const unpriceable = []
  for (const c of joinCtx?.candidates ?? []) {
    const w = joinWait(c.requirements, { ...joinCtx.state, expPerSec: expRate })
    // Infinity is a REAL answer — "not inside one life at these rates" (a
    // gym or kill leg longer than the install window) — but JSON writes it
    // as null, indistinguishable from unknown. Report it with the blockers,
    // whose `why` says which leg and how long, rather than as a forecast.
    if (w.known && !isFinite(w.hours)) {
      unpriceable.push({ name: c.name, blockers: w.blockers, why: 'unreachable in one install window' })
    } else if (w.known) {
      byFaction.set(c.name, {
        name: c.name,
        rep: c.rep,
        favor: c.favor,
        augs: c.augs,
        joinWaitHours: w.passiveHours,
        joinWorkHours: w.activeHours,
      })
      joinForecasts.push({ name: c.name, hours: w.hours, activeHours: w.activeHours, blockers: w.blockers })
    } else {
      unpriceable.push({ name: c.name, blockers: w.blockers })
    }
  }

  // THE TRAJECTORY. Rep gain is linear in hacking level and the level rises
  // all grind long, so the schedule prices hours off trajectory.js's closed
  // form — calibrated by the measured base rate, shaped by the measured exp
  // flow. Either measurement missing degrades exactly to the old constant-
  // rate arithmetic (repModel handles the flat case; null skips the hooks).
  const traj = repModel({
    baseRepPerSec: base,
    hacking: joinCtx?.state?.hacking,
    hackingExp: expNow,
    hackingMult: joinCtx?.state?.hackingMult,
    expPerSec: expRate,
  })
  const hooks = traj
    ? { repTime: (rep, fav, startH) => traj.hoursFor(rep, fav, startH), repAmount: (startH, h, fav) => traj.repBetween(startH, h, fav) }
    : {}

  // The base rate for pricing: measured wins; the formula estimate stands in
  // when nothing has measured (first passes of a life); 1 only if even the
  // estimate cannot be built — and `estimated` says which arm was used.
  const baseForPlan = base ?? joinCtx?.state?.baseRepEstimate ?? 1

  // The install-boundary hook: prices any rep target through favor.js's
  // ladder, from the MEASURED window and multiplier growth (lifetimes
  // ledger). Absent window inputs, the hook is absent and the walk keeps its
  // continuous arithmetic — the old fiction, but only where nothing measured.
  const wctx = joinCtx?.state
  if (wctx?.windowH > 0) {
    hooks.ladder = (a) =>
      repLadder(a.repReq, {
        windowH: wctx.windowH,
        remainingWindowH: Math.max(0.05, wctx.windowH - (wctx.lifeAgeH ?? 0) - (a.extraStartH ?? 0)),
        baseRepPerSec: baseForPlan,
        favor: a.favor,
        currentRep: a.currentRep,
        hoursNow: a.hoursNow,
        rateGrowthPerCycle: wctx.rateGrowthPerCycle,
        // The donation terminal: at favour 150 the remaining rep is a money
        // question priced by income — the ladder stops climbing the moment
        // that path is the cheaper one. Half-specified inputs disarm it
        // inside repLadder rather than guessing.
        donateAt: wctx.donateAt,
        repMult: wctx.donateRepMult,
        nodeWorkRepMult: wctx.donateNodeMult,
        incomePerSec: wctx.donateIncome,
        money: wctx.money,
      })
  }

  // THE CROSSING RACE. Crossing 150 favour at ANY faction opens money->NFG
  // (every faction sells NeuroFlux), and the value walk cannot see that from
  // aug lists alone — live, the schedule ground BitRunners at favour 47 while
  // NiteSec and CyberSec both sat ~16 favour from the unlock. So every
  // below-threshold faction gets one SYNTHETIC unlock in its walk:
  //
  //   repReq  = rep + banked-rep-to-150   (additive across installs — FV10 —
  //             hence `banked: true`, exempting it from the window ladder)
  //   value   = one window's income converted to NFG levels at donation
  //             prices x the CURRENT basket's per-level ln. One install's
  //             worth, though the unlock recurs — deliberately conservative.
  //
  // The per-level ln comes from the live NFG offer through the same logValue
  // as every real augmentation, so a basket change reprices the crossing too.
  if (wctx?.donateIncome > 0 && wctx.windowH > 0 && wctx.donateNodeMult && wctx.donateRepMult) {
    const nfgOffer = offers.find((of) => of.name === NFG)
    const lnPerLevel = nfgOffer ? logValue(nfgOffer.mults, joinCtx?.channels, joinCtx?.channelWeights ?? null) : 0
    if (nfgOffer && lnPerLevel > 0) {
      const budget = wctx.donateIncome * wctx.windowH * 3600
      const k = nfgLevelsByDonation(budget, nfgOffer.repReq, wctx.donateRepMult, wctx.donateNodeMult)
      if (k > 0) {
        for (const f of byFaction.values()) {
          const gap = repToCross(f.favor)
          if (gap === null || gap === 0) continue // unreadable, or the pipe is already open
          f.augs.push({
            name: `(cross the donation threshold -> ${k} NFG/install)`,
            repReq: f.rep + gap,
            mults: { hacking: Math.exp(k * lnPerLevel) },
            banked: true,
          })
        }
      }
    }
  }

  hooks.channelWeights = joinCtx?.channelWeights ?? null
  hooks.channels = joinCtx?.channels ?? undefined
  // THE DESK-PATH SENTINEL. The megacorp path ranks low on priced terms, but
  // some of its terms (charisma weighting, salary) are deliberately unpriced
  // — and "it ranks low so the gaps don't matter" is circular. So compute the
  // UTOPIAN bound instead: instant CTO, free maxed charisma, zero training —
  // every unpriced term at its ceiling. While the schedule's best rate holds
  // a wide margin over that bound, no pricing error can flip the ranking; the
  // moment the margin closes (walks thinning, NFG escalating), this flag
  // fires and the honest next steps are a calibration desk stint and a
  // derived charisma weight. Measured at build time: bound 0.306 ln/h vs a
  // 3.82 cycle — 12x — with the tail segments already below the bound.
  let deskBound = null
  try {
    const cto = SOFTWARE_TRACK[SOFTWARE_TRACK.length - 1]
    const utopianRate = companyRepPerSec(cto, {
      hacking: joinCtx?.state?.hacking,
      charisma: 975, // maxed for free — the bound, not a claim
      companyRepMult: joinCtx?.state?.companyCtx?.companyRepMult,
      nodeCompanyRepMult: joinCtx?.state?.companyCtx?.nodeCompanyRepMult,
    })
    if (utopianRate > 0) {
      let best = 0
      for (const c of joinCtx?.candidates ?? []) {
        if (!MEGACORPS.some((m) => m.faction === c.name)) continue
        const lnCatalog = (c.augs ?? []).reduce((a, x) => a + logValue(x.mults, undefined, joinCtx?.channelWeights ?? null), 0)
        if (!(lnCatalog > 0)) continue
        // 400k company rep at the utopian rate, plus a generous faction grind
        // for the catalog at the measured base rate — both favouring the desk.
        const joinH = 400e3 / utopianRate / 3600
        const grindH = 350e3 / Math.max(baseForPlan, 0.1) / 3600
        best = Math.max(best, lnCatalog / (joinH + grindH))
      }
      if (best > 0) deskBound = Math.round(best * 1000) / 1000
    }
  } catch {
    /* the sentinel is advisory — a failed bound publishes null, never blocks */
  }

  const plan = planSchedule([...byFaction.values()], baseForPlan, hooks)

  // THE CHARISMA PROBE — pricing a channel that transmits through a PATH
  // CHOICE. Charisma does nothing for the hacking path; it compresses the
  // megacorp desk wall (chaMult divides the exp-curve exponent), and the
  // desk-path sentinel showed the ranking is no longer robust to leaving
  // that unpriced. So probe: re-run the desk forecast at chaMult x1.5 (and
  // chaExpMult x1.5), and weight each channel by the rate gained PAST THE
  // INCUMBENT best segment — charisma bought for a path never taken buys
  // nothing, so a losing probe prices at exactly zero (objective.js's
  // pathGainWeight). Persisted in this file's output and merged into the
  // basket NEXT pass: the probe needs this pass's best rate, so the weights
  // trail one pass — a 5-minute lag against hours-scale decisions.
  let chaWeights = null
  try {
    const ctx = joinCtx?.state?.companyCtx
    const wm = joinCtx?.weightsMeta
    const bestRate = plan.segments?.[0]?.rate ?? 0
    if (ctx && wm?.source === 'derived' && wm.remainingWindows > 0 && joinCtx?.state?.windowH > 0) {
      const K = 1.5
      const grindH = 350e3 / Math.max(baseForPlan, 0.1) / 3600
      const probeDesk = (field) => {
        let best = 0
        for (const c of joinCtx.candidates ?? []) {
          if (!MEGACORPS.some((m) => m.faction === c.name)) continue
          const repReq = (c.requirements ?? []).find((r) => r?.type === 'companyReputation')?.reputation
          if (!(repReq > 0)) continue
          const lnCat = (c.augs ?? []).reduce((a, x) => a + logValue(x.mults, undefined, joinCtx.channelWeights ?? null), 0)
          if (!(lnCat > 0)) continue
          const inputs = (mult) => ({
            company: MEGACORPS.find((m) => m.faction === c.name).company,
            currentRep: ctx.repByCompany?.[MEGACORPS.find((m) => m.faction === c.name).company] ?? 0,
            favor: 0,
            hacking: ctx.hacking,
            hackExp: joinCtx.state.hackingExp,
            hackExpRate: joinCtx.state.expPerSec,
            hackMult: joinCtx.state.hackingMult,
            charisma: ctx.charisma,
            chaExp: ctx.chaExp,
            chaMult: field === 'chaMult' ? (ctx.chaMult ?? 1) * mult : ctx.chaMult,
            chaExpMult: field === 'chaExpMult' ? (ctx.chaExpMult ?? 1) * mult : ctx.chaExpMult,
            intelligence: ctx.intelligence,
            companyRepMult: ctx.companyRepMult,
            nodeCompanyRepMult: ctx.nodeCompanyRepMult,
            nodeCompanyExpMult: ctx.nodeCompanyExpMult,
            uniChaExpPerSec: ctx.uniChaExpPerSec,
          })
          const h0 = hoursToCompanyRep(repReq, inputs(1))
          const h1 = hoursToCompanyRep(repReq, inputs(K))
          if (h0?.hours > 0 && h1?.hours > 0) {
            // The gain that counts: the probed desk rate past the INCUMBENT
            // (the better of the unprobed desk and the schedule's best) —
            // a probe that fails to cross either prices at <= 0.
            const r0 = lnCat / (h0.hours + grindH)
            const r1 = lnCat / (h1.hours + grindH)
            best = Math.max(best, r1 - Math.max(r0, bestRate))
          }
        }
        return best
      }
      const rawH = 1 + wm.remainingWindows * ((wm.eBudget ?? 0) + (wm.eRep ?? 0))
      const remainingHours = wm.remainingWindows * joinCtx.state.windowH
      for (const [key, field] of [['charisma', 'chaMult'], ['charisma_exp', 'chaExpMult']]) {
        const w = pathGainWeight({ rateGain: probeDesk(field), lnK: Math.log(K), remainingHours, rawHacking: rawH })
        if (w !== null && w > 0) (chaWeights ??= {})[key] = Math.round(w * 10000) / 10000
      }
    }
  } catch {
    /* the probe is additive — failure leaves charisma unpriced, as before */
  }

  const out = {
    at: new Date(now).toISOString(),
    lastAugReset: info?.lastAugReset,
    measuredBaseRepPerSec: base,
    estimated: base === null,
    estimatedBaseRepPerSec: base === null ? (joinCtx?.state?.baseRepEstimate ?? null) : null,
    hackingExp: expNow ?? null,
    expPerSec: expRate,
    trajectory: traj ? (traj.grows ? 'growing' : 'flat') : 'unavailable',
    windowH: wctx?.windowH ?? null,
    lifeAgeH: wctx?.lifeAgeH != null ? Math.round(wctx.lifeAgeH * 100) / 100 : null,
    rateGrowthPerCycle: wctx?.rateGrowthPerCycle ?? null,
    // Which arm produced each driver, whether any clamp binds, and the
    // rolling actual/predicted per forecast family — the drift line.
    windowMeta: wctx?.windowMeta ?? null,
    // The utopian ceiling on the megacorp desk path vs the schedule's best
    // priced rate. margin >= 2 means no pricing error on the unpriced desk
    // terms can flip the ranking; below 2, run a calibration desk stint and
    // derive the charisma weight before trusting the ranking further.
    deskSentinel: deskBound !== null && plan.segments?.[0]?.rate > 0
      ? { deskBoundLnPerH: deskBound, bestRate: +plan.segments[0].rate.toFixed(3), margin: +(plan.segments[0].rate / deskBound).toFixed(2), attention: plan.segments[0].rate / deskBound < 2 }
      : null,
    forecastScores: (() => {
      try {
        return ledgerScores(JSON.parse(ns.read('/tel/lifetimes.txt') || '[]'))
      } catch {
        return null
      }
    })(),
    reps,
    favors: Object.fromEntries([...byFaction].map(([k, v]) => [k, v.favor])),
    companyReps,
    measuredCompanyRates,
    workingFaction: plan.current?.faction ?? null,
    chaWeights,
    joinForecasts,
    unpriceable,
    ...plan,
  }
  ns.write(SCHEDULE, JSON.stringify(out, null, 2), 'w')
  return out
}

/**
 * Money that must be HELD to buy a faction INVITATION, not spent.
 *
 * Daedalus — the faction that sells The Red Pill, and so the only route out of
 * the BitNode — admits on 30 distinct augmentations, a hacking level, and
 * **$100b in hand**. Money in hand is the one requirement a spender can
 * destroy, and every spender in this collection was doing exactly that: live in
 * BitNode 1 with the augmentation count already satisfied, hacking at 5994
 * against an exit bar of 3000, and income at $477b/h, the balance fell from
 * $6.02b to $5.10b while buyserv.js converted it into cloud servers — which do
 * not even survive an install. Nothing in the budget knew the join existed, so
 * the $100b gate was not far away, it was UNREACHABLE.
 *
 * Read from the live requirement rather than a constant: the figure comes from
 * ns.singularity.getFactionInviteRequirements, so a BitNode that scales it, or
 * a game update that changes it, needs no edit here.
 *
 * Claims ZERO — a known nothing, not an unknown — when the faction is already
 * joined, when the requirement is met, or when there is nothing to price. Only
 * an unreadable candidate set yields null, which blocks spending by design.
 */
/** The faction whose augmentation ends the BitNode. */
const EXIT_FACTION = 'Daedalus'

function joinMoneyClaim(candidates, player) {
  if (!Array.isArray(candidates)) return null
  const money = player?.money
  if (typeof money !== 'number' || !isFinite(money)) return null
  let want = 0
  for (const c of candidates ?? []) {
    // Only the faction that ends the node. Holding cash for every faction's
    // money requirement would starve the fleet for invitations the run has no
    // reason to want.
    if (c?.name !== EXIT_FACTION) continue
    for (const need of moneyNeeds(c.requirements)) {
      if (money < need && need > want) want = need
    }
  }
  return want
}

/**
 * The exit faction's money REQUIREMENT, independent of what we currently hold.
 *
 * joinMoneyClaim answers a different question — "how much must I keep back" —
 * and correctly returns 0 once the balance covers it. bindingGate needs the
 * requirement itself, because "we can afford it" and "we have joined" are
 * different states and only the second one ends the gate.
 */
function exitFactionMoneyReq(candidates) {
  if (!Array.isArray(candidates)) return null
  let req = 0
  for (const c of candidates) {
    if (c?.name !== EXIT_FACTION) continue
    for (const need of moneyNeeds(c.requirements)) if (need > req) req = need
  }
  return req > 0 ? req : null
}

/** Every `money` requirement in a (possibly nested) requirement tree. */
function moneyNeeds(req, out = []) {
  if (!req || typeof req !== 'object') return out
  if (Array.isArray(req)) {
    for (const r of req) moneyNeeds(r, out)
    return out
  }
  if (req.type === 'money' && typeof req.money === 'number' && isFinite(req.money)) out.push(req.money)
  for (const k of ['conditions', 'condition']) if (req[k]) moneyNeeds(req[k], out)
  return out
}

/** 0GB read that cannot throw; absent or malformed both yield null. */
function readJson(ns, path) {
  try {
    return JSON.parse(ns.read(path) || 'null')
  } catch {
    return null
  }
}

/**
 * How much installing would multiply future faction-work reputation, via the
 * favour it converts banked reputation into.
 *
 * Returns 1 (no gain) on any doubt — no Singularity, no faction, an unreadable
 * figure. Overstating this would make installing look better than it is, which
 * is the direction this gate has already failed in twice.
 */
function favorGainOf(sing, faction, canJoin, o = {}) {
  if (!canJoin || !faction) return 1
  try {
    const favor = sing.getFactionFavor(faction)
    const rep = sing.getFactionRep(faction)
    if (!isFinite(favor) || !isFinite(rep) || favor < 0 || rep < 0) return 1
    const after = addRepToFavor(favor, rep)
    const gain = (1 + after / 100) / (1 + favor / 100)
    if (!isFinite(gain) || gain < 1) return 1

    // --- and the discontinuity the smooth term cannot see -------------------
    //
    // The ratio above prices favour as a RATE bonus, which is smooth and small:
    // 120 favour to 125 is worth 2%. It completely misses what happens at 150,
    // where reputation stops having exactly one source. Below the threshold the
    // only way to get reputation is to spend time; above it money buys it too,
    // permanently, for the rest of the BitNode.
    //
    // That is the fix for the thing that has actually been costing us. We have
    // destroyed $100m-$440m of stranded cash at every install, not because the
    // gate mistimed anything but because below 150 favour surplus money
    // converts into nothing at all. Crossing the threshold is what makes cash
    // worth holding, and until now the gate could not see the crossing coming.
    //
    // WHY FactionWorkRepGain IS PASSED AS 1 HERE, WHICH LOOKS WRONG.
    // It appears in BOTH halves of the ratio and cancels. reputation.ts:13
    // multiplies faction WORK rep by it, donation.ts:9 multiplies DONATION rep
    // by the same factor, and `baseRepPerSec` is MEASURED from real reputation
    // deltas in the live game, so it already carries it:
    //
    //     base    = raw * FWRG                 (measured, favour divided out)
    //     r_work  = base * (1 + favor/100)     = raw * FWRG * favourMult
    //     r_donate= income/1e6 * faction_rep * FWRG
    //     ratio   = income * faction_rep / (1e6 * raw * favourMult)   <- no FWRG
    //
    // Passing BitNode 4's real 0.75 would understate the unlock by 25%. This is
    // the opposite of the usual error with this constant, and it is only safe
    // because the rate is measured rather than derived — which is why the guard
    // below refuses to price anything when it is not.
    const measured = o.baseRepPerSec
    if (!(measured > 0)) return gain
    const uplift = donationUplift({
      favorAfter: after,
      baseRepPerSec: measured,
      incomePerSec: o.incomePerSec,
      repMult: o.repMult,
      nodeWorkRepMult: 1,
    })
    return isFinite(gain * uplift) ? gain * uplift : gain
  } catch {
    return 1
  }
}

/**
 * The install window and per-install multiplier growth, measured from the
 * lifetimes ledger. Median for the window (a single 6h outlier life must not
 * stretch every ladder); geometric mean for growth (it compounds). Fallbacks
 * are the 2026-09-15 measurements, dated at the call site, replaced as soon
 * as three real samples exist.
 */
function measureWindow(ns) {
  // All logic lives in scorecard.js (pure, SC1-SC3 tested — including the
  // regression where a min-3-samples guard here silently priced every ladder
  // at the dated fallback g while the ledger had already measured 6x more).
  // This wrapper only reads the file.
  try {
    return measureFromLedger(JSON.parse(ns.read('/tel/lifetimes.txt') || '[]'))
  } catch {
    return measureFromLedger([])
  }
}

/**
 * Score the previous pass's income prediction against what actually happened
 * — the prospective calibration trajectory.js's incomeModel demands, since
 * income has no history series to check backward against. Returns null when
 * there is nothing scoreable, which the caller publishes as-is: a missing
 * score means "no prior sample", never "checked and fine".
 */
function scoreIncome(prevIncome, incomePerSec) {
  if (!prevIncome || !(incomePerSec > 0) || !(prevIncome.incomePerSec > 0)) return null
  const dtH = (Date.now() - Date.parse(prevIncome.at)) / 3600000
  if (!(dtH > 0.02)) return null
  const prevModel = incomeModel(prevIncome)
  const predicted = prevModel ? prevIncome.incomePerSec * prevModel.factorAt(dtH) : null
  if (!(predicted > 0)) return null
  return {
    overHours: Math.round(dtH * 100) / 100,
    predicted: Math.round(predicted),
    actual: Math.round(incomePerSec),
    // Persistently ABOVE 1 = income outgrew (level+50), the fleet/retarget
    // share — the lower-bound claim holding. Below ~1 = the shape is wrong
    // and must not keep shipping silently.
    actualOverPredicted: Math.round((incomePerSec / predicted) * 1000) / 1000,
  }
}

/** The model's inputs at this instant, persisted so the NEXT pass can score. */
function makeIncomeSample(incomePerSec, player, schedule) {
  return {
    at: new Date().toISOString(),
    incomePerSec,
    hacking: player.skills?.hacking,
    hackingExp: schedule?.hackingExp,
    hackingMult: player.mults?.hacking,
    expPerSec: schedule?.expPerSec,
  }
}

async function act(ns, canJoin, info) {
  const flags = ns.flags([
    ['dry', false],
    ['no-install', false],
    // A HUMAN OVERRIDE, and deliberately not a tuning knob. It forces the
    // install the gate would otherwise defer, for the one situation the gate
    // cannot reason its way out of: the FIRST life of a BitNode has no rho
    // (scorecard.achievableRate needs completed lives, and there are none), so
    // it falls back to comparing this life's wall-clock average — which any
    // dead time inflates, making it hold longer the longer it has been stuck.
    // One forced install seeds the ledger and every later life in the node
    // decides on measured rho instead.
    //
    // It overrides the RATE decision only. Everything that makes an install
    // possible at all still applies: a plan must exist, it must be affordable,
    // and the drift guard still re-prices every purchase. The gate's own
    // verdict is published first and quoted in the log, so the record always
    // says what the model wanted and that a human disagreed.
    ['install-now', false],
  ])
  ns.disableLog('ALL')

  const todo = []
  const did = []

  const player = ns.getPlayer()
  // THE CONTRACT STREAM, forecast rather than measured: one every ~13 minutes
  // is invisible to a 5-minute income sample and is not script income at all.
  // Folded into every money leg below (join money, the exit hoard) as a rate
  // alongside script income; NOT into the script-income calibration, which
  // scores a different quantity. hasHackingFaction is approximated by "any
  // faction joined" — the first faction this stack ever joins offers hacking
  // work, and the term only moves reputation between money and rep shares.
  const contractForecast = (() => {
    try {
      const sf = totalSfLevels(info)
      const ct = readJson(ns, '/tel/ctauto.txt')
      return contractIncome({
        totalSourceFileLevels: sf,
        nodeContractMoney: bitNodeMults(info?.currentNode)?.CodingContractMoney,
        hasHackingFaction: (player.factions?.length ?? 0) > 0,
        hasJob: Object.keys(player.jobs ?? {}).length > 0,
        pending: typeof ct?.lastScanFound === 'number' ? ct.lastScanFound : 0,
      })
    } catch {
      return null
    }
  })()
  const contractMoneyPerSec = contractForecast?.moneyPerSec ?? 0
  // THE STOCK MARKET ENTRY, priced and — for now — refused with its reason:
  // the expected return needs a 4S forecast this run has not bought, so
  // `edgePerHour` is null and stockplan says so rather than guessing. What
  // this buys the loop is the visible number: the entry cost, the capital,
  // and the exact sentence naming the missing input. The four ownership
  // reads are 0.05GB each; getConstants is free.
  const stockForecast = (() => {
    try {
      const nm = bitNodeMults(info?.currentNode)
      const owned = { wse: ns.stock.hasWseAccount(), tix: ns.stock.hasTixApiAccess(), data4s: ns.stock.has4SData(), api4s: ns.stock.has4SDataTixApi() }
      const entry = stockEntryCost(owned, { FourSigmaMarketDataCost: nm?.FourSigmaMarketDataCost, FourSigmaMarketDataApiCost: nm?.FourSigmaMarketDataApiCost }, ns.stock.getConstants())
      return { owned, entry, verdict: stockVerdict({ entry, capital: player.money, edgePerHour: null, remainingH: null }) }
    } catch (e) {
      return { error: String(e).slice(0, 120) }
    }
  })()
  const sing = ns.singularity
  // The derived objective (objective.js) — computed in the offers block once
  // a plan exists to measure elasticities against; every earlier consumer
  // (the city-faction pricing) sees null and prices flat, exactly as before.
  let channelWeights = null
  let channelsUsed = [...RATE_CHANNELS]
  let weightsMeta = { source: 'flat' }

  // --- capability probes, each cheap and done once ---------------------------
  // `canJoin` is now passed in from main(), derived through sfgate.js rather
  // than by calling a singularity function and catching the throw. See "THE
  // PROBE" in this file's header: under an ns.ramOverride the old probe was
  // fatal, because the call's RAM is charged before its body runs.
  const canWork = canJoin && typeof sing.workForFaction === 'function'
  const canBuyAug = canJoin && typeof sing.purchaseAugmentation === 'function'
  const canInstall = canJoin && typeof sing.installAugmentations === 'function'

  // --- 1. accept invitations -------------------------------------------------
  const invites = canJoin ? sing.checkFactionInvitations() : (player.factionInvitations ?? [])
  // Non-exclusive invitations are free: joining costs nothing and can only add
  // augmentations, so they are accepted without analysis.
  const wanted = invites.filter((f) => !CITY_FACTIONS.includes(f))
  for (const f of wanted) {
    if (canJoin && !flags.dry) {
      if (sing.joinFaction(f)) did.push(`joined ${f}`)
    } else {
      todo.push(`Accept the ${f} invitation (Factions tab).`)
    }
  }

  // EXCLUSIVE (city) INVITATIONS ARE PRICED, NOT REFUSED.
  //
  // This used to skip every one of them, on the stated grounds that "joining
  // one locks out the other five". That is FALSE. The enemy sets
  // (Faction/FactionInfo.tsx:495-553) are not all-or-nothing:
  //
  //     Sector-12 and Aevum ban the other four but NOT each other
  //     Chongqing, New Tokyo and Ishima ban S-12/Aevum/Volhaven, not each other
  //     Volhaven bans all five
  //
  // So up to THREE can be held at once, and refusing all of them forfeited real
  // augmentations for a constraint that does not exist as described. Refusing
  // everything is never optimal: whatever set we would eventually want, joining
  // it is at least as good as joining nothing.
  //
  // The choice is made over ALL cities at once, not invitation by invitation,
  // so an early invite from a weak group cannot lock out a better group that
  // has not invited us yet. Enemy lists come from the game
  // (ns.singularity.getFactionEnemies, Singularity.ts:740) rather than a copy
  // here that could drift.
  const cityInvites = invites.filter((f) => CITY_FACTIONS.includes(f))
  if (cityInvites.length) {
    if (!canJoin || flags.dry) {
      todo.push(`${cityInvites.join(', ')} invite(s) pending — city factions, need Singularity to price and join.`)
    } else {
      // Owned set, computed locally — the file's allCount is built later, in
      // the purchase block. A TDZ reference to it here crashed the entire
      // pass (loudly: health:error), which is how this reordering was caught.
      const cityOwned = new Set(sing.getOwnedAugmentations(true))
      const candidates = CITY_FACTIONS.map((name) => {
        let value = 0
        let enemies = []
        const augs = []
        try {
          enemies = sing.getFactionEnemies(name)
          for (const aug of sing.getAugmentationsFromFaction(name)) {
            if (cityOwned.has(aug) && aug !== NFG) continue
            value += logValue(sing.getAugmentationStats(aug), channelsUsed, channelWeights)
            augs.push(aug) // distinct unowned — a Daedalus ticket regardless of multipliers
          }
        } catch {
          // Unreadable: value 0 and no enemies, so it is never chosen and never
          // blocks a choice. An unknown must not present as attractive.
        }
        return { name, enemies, value, augs }
      })
      // TICKET-AWARE JOIN. City augs are near-zero multipliers, so on M alone
      // they always declined — right until Daedalus's COUNT gate became the
      // binding endgame constraint and the hacking factions ran dry (NFG
      // walled at ~$49T/level, ~4 distinct augs left). Then each city aug is
      // a ticket, and the cities are the only source. Priced as opportunity
      // cost — one window of the best available work per ticket — and gated on
      // a genuine shortfall so early lives never join a combat-aug city for
      // nothing. daedalusNeed/installedCount are already in scope here.
      // Self-contained here: the offers list and daedalusNeed are built later
      // in the file, so recompute the shortfall from data in scope now.
      const cityDaedalusNeed = bitNodeMults(info?.currentNode)?.DaedalusAugsRequirement ?? 0
      const distinctHeld = [...cityOwned].filter((a) => a !== NFG).length + (cityOwned.has(NFG) ? 1 : 0)
      let availFromJoined = 0
      for (const f of player.factions) {
        try {
          for (const a of sing.getAugmentationsFromFaction(f)) if (a !== NFG && !cityOwned.has(a)) availFromJoined++
        } catch {
          /* unreadable faction contributes nothing to the count */
        }
      }
      const ticketsShort = cityDaedalusNeed > 0 ? Math.max(0, cityDaedalusNeed - distinctHeld - availFromJoined) : 0
      // The schedule and window are computed later this pass; read the PRIOR
      // pass's published figures (slowly-varying — a join threshold does not
      // need this pass's freshest). ticketValue = one window of the best
      // available work per ticket, the opportunity cost of joining to grind it.
      const priorSched = readJson(ns, SCHEDULE)
      const bestSegRate = priorSched?.segments?.[0]?.rate ?? 0
      const priorWindowH = priorSched?.windowH ?? 0
      const ticketValue = ticketsShort > 0 && bestSegRate > 0 && priorWindowH > 0 ? bestSegRate * priorWindowH : 0
      const pick = bestCompatibleSet(candidates, { ticketValue, ticketsShort })
      if (pick.error) {
        todo.push(`city factions could not be priced exactly (${pick.error}) — none joined`)
      } else {
        for (const f of cityInvites) {
          if (!pick.chosen.includes(f)) {
            todo.push(`${f} invite declined: the best compatible city set is [${pick.chosen.join(', ') || 'none'}] worth ${pick.value.toFixed(4)} ln(M)`)
            continue
          }
          if (sing.joinFaction(f)) did.push(`joined ${f} (city set [${pick.chosen.join(', ')}], ${pick.value.toFixed(4)} ln(M))`)
        }
      }
    }
  }

  // --- 2. make sure reputation is actually being earned ----------------------
  // This is the failure that matters most: with no faction work running, the
  // one quantity that cannot be bought earns nothing, and everything else in
  // the game looks perfectly healthy while it happens.
  // RE-READ. `player` was snapshotted at the top of this pass (ns.getPlayer(),
  // above), and step 1 just JOINED factions — so the snapshot's list is stale
  // by construction, and it is stale in the direction that does maximum damage:
  // it reads as EMPTY on precisely the pass that fixed the emptiness.
  //
  // Live in BitNode 5, one published record contained both of these at once:
  //   did:  ["joined Netburners", "joined CyberSec", "joined NiteSec"]
  //   todo: ["NO FACTION JOINED — reputation is earning ZERO. ..."]
  // The alarming line is the visible half. The expensive half is silent: the
  // `factions.length === 0` branch below skips work selection entirely, so the
  // pass joined three factions and then started no work, earning zero
  // reputation for a full 240s cooldown before the next pass re-read the list.
  //
  // ns.getPlayer() is already referenced above, so the fresh read costs no RAM.
  const factions = ns.getPlayer().factions

  // READ THE WORK STATE FROM SINGULARITY, NOT FROM getPlayer().
  //
  // This used to be `player.currentWork`, and `ns.getPlayer()` does not return
  // that field: NetscriptFunctions.ts:1371-1389 builds the payload by hand and
  // it carries hp/skills/exp/mults/city/numPeopleKilled/money/location/
  // totalPlaytime/jobs/factions/entropy/karma — and nothing else. So `work` was
  // ALWAYS undefined, `!work` was ALWAYS true, and this branch called
  // workForFaction on every single launch.
  //
  // That is silent in the worst way. Reputation still accrues, so the telemetry
  // says "working for X, focused" and looks correct; what actually happens is
  // that each launch restarts the work and re-steals UI focus. Under a watchdog
  // that relaunches on an interval, that is a script taking over the screen
  // every few minutes for no benefit — the same failure shape as homeup.js.
  //
  // `player.focus` is absent from the same payload, which made the refocus
  // branch below unreachable: `undefined === false` is false, so an unfocused
  // faction work session was never corrected despite costing 20% of the rate.
  const work = canJoin ? sing.getCurrentWork() : null

  // --- offers, gathered EARLY -----------------------------------------------
  //
  // Moved above the faction-work decision because that decision now prices
  // factions by the augmentations they gate, and cannot do it without this
  // data. It used to sit in section 4, which meant the schedule read an empty
  // `offers` and silently ranked every faction at zero — caught by checking the
  // declaration order rather than by any runtime error, because an empty offer
  // list is a perfectly well-formed input that just answers "nothing is worth
  // working".
  //
  // Pure gathering: no purchases happen here, so moving it changes what the
  // decision can see and nothing else.
  let plan = null
  // Hoisted: the forward projection in section 5 re-plans against the SAME
  // offer set at a larger budget, so these must outlive this block. Declaring
  // them inside it left `offers` undefined at the gate call — caught by
  // measuring before deploy rather than by a runtime throw in the live game.
  let offers = []
  let installedCount = new Map()
  let allCount = new Map()
  // Hoisted for the same reason as the three above: the install gate reads it
  // far below this block, and a `const` inside the block is simply not in scope
  // there. Live, that threw `ReferenceError: ticketsWanted is not defined` and
  // took the whole pass down — the same shape as the `allCount` TDZ error, and
  // the reason those three carry the note they do. 0 means "no count gate",
  // which is the correct reading when the augmentation path is unavailable.
  let ticketsWanted = 0
  if (canBuyAug) {
    const count = (list) => list.reduce((m, a) => m.set(a, (m.get(a) ?? 0) + 1), new Map())
    installedCount = count(sing.getOwnedAugmentations(false))
    allCount = count(sing.getOwnedAugmentations(true))
    const held = []
    for (const [name, n] of allCount) {
      for (let i = 0; i < n - (installedCount.get(name) ?? 0); i++) held.push(name)
    }
    const r = BASE_PRICE_MULT // SF11 is not held; genericPriceMultiplier(lvl) when it is
    const unqueue = Math.pow(r, held.filter((a) => !isSoa(a)).length)

    const donateNeed = favorNeededToDonate(1) // BN4 leaves FavorToDonateToFaction at 1
    const fwrg = bitNodeMults(info?.currentNode)?.FactionWorkRepGain ?? null
    for (const f of player.factions) {
      const rep = sing.getFactionRep(f)
      // Past the donation threshold a rep wall is a PRICE (donation.ts:8) —
      // attached per offer so augplan can charge it as a fixed cost. Left
      // absent below the threshold or with an unreadable BitNode term, and
      // the wall stands exactly as before.
      const donatable = sing.getFactionFavor(f) >= donateNeed && fwrg !== null
      for (const aug of sing.getAugmentationsFromFaction(f)) {
        // NeuroFlux is the only repeatable augmentation (AugmentationHelpers.ts:117-120).
        if (allCount.has(aug) && aug !== NFG) continue
        const repReq = sing.getAugmentationRepReq(aug)
        offers.push({
          name: aug,
          faction: f,
          baseCost: sing.getAugmentationPrice(aug) / (isSoa(aug) ? 1 : unqueue),
          repReq,
          factionRep: rep,
          ...(donatable && repReq > rep
            ? { donationCost: donationForRep(repReq - rep, player.mults?.faction_rep ?? 1, fwrg) }
            : {}),
          mults: sing.getAugmentationStats(aug),
          prereqs: sing.getAugmentationPrereq(aug),
          // The live NFG price already carries 1.14^getLevel(), so the planner
          // starts its own chain at 0 rather than double-counting the level.
          nfgLevel: 0,
        })
      }
    }

    // THE ENDGAME OBJECTIVE rides every plan: Daedalus admits at a distinct-
    // augmentation count (30 in BN4, read from the verified table), and each
    // cheap unowned augmentation is a TICKET toward it — swept with leftover
    // budget after the M-optimal picks, never displacing them.
    // Read from the BN1-verified table, with NO literal fallback: an unknown
    // node reads null, ticketsWanted goes 0, and the sweep simply stands down
    // — degrading to the pure-M objective beats guessing the count gate.
    const daedalusNeed = bitNodeMults(info?.currentNode)?.DaedalusAugsRequirement
    ticketsWanted = daedalusNeed > 0 ? Math.max(0, daedalusNeed - installedCount.size) : 0
    // Context for augmentations whose value is NOT in their multipliers —
    // money, granted programs, the focus penalty (objective.js ONEOFF_EFFECTS).
    // Without it those score M = 1 and are filed 'no-value' at every price,
    // which is why CashRoot Starter Kit ($1m + BruteSSH.exe every install) was
    // never bought. eBudget and remainingWindows arrive with the DERIVED
    // weights, so on a flat-weights pass this stays unpriced and says so
    // rather than guessing a coefficient.
    const liveMoney = ns.getServerMoneyAvailable('home')
    const oneoffBase = {
      money: liveMoney,
      // ownedPrograms is deliberately NOT passed. It would have to be the set
      // we hold at the moment the grant LANDS, which is immediately after an
      // install — and prestigeHomeComputer wipes programs
      // (Server/ServerHelpers.ts:226-239, the same reset that spares maxRam and
      // cpuCores). So a granted program is worth its full darkweb price every
      // life no matter what is on the drive today, and reading the current set
      // would understate the grant. It also cost 0.20GB of ns.ls, which pushed
      // this script past its own ramOverride ceiling — [R5] caught that.
      // focusPenalty() is only paid when work is UNFOCUSED
      // (PlayerObjectGeneralMethods.ts:622).
      unfocused: work?.focused === false,
    }

    const planArgs = {
      offers,
      money: liveMoney,
      r,
      nodeMoneyMult: 1, // already in the live price
      owned: [...installedCount.keys()],
      soaOwned: [...allCount.keys()].filter(isSoa).length,
      ticketsWanted,
      oneoff: oneoffBase,
    }
    plan = planPurchases(planArgs)

    // ------------------------------------------------------------------
    // THE DERIVED OBJECTIVE (objective.js has the model). Two stages,
    // because the weights need elasticities and the elasticities need a
    // plan: the flat plan above is the probe, the weighted re-plan below is
    // what ships. The elasticities are the REAL optimiser's response to a
    // 50% bigger budget and to reputation arriving 50% faster (donation
    // costs shrunk in step — past the threshold faster rep IS cheaper rep),
    // measured on this pass's actual offers.
    // ------------------------------------------------------------------
    channelWeights = null
    weightsMeta = { source: 'flat' }
    if (plan && plan.logM > 1e-9) {
      try {
        const K = 1.5
        const richer = planPurchases({ ...planArgs, money: planArgs.money * K })
        const faster = planPurchases({
          ...planArgs,
          offers: offers.map((of) => ({
            ...of,
            factionRep: (of.factionRep ?? 0) * K,
            ...(typeof of.donationCost === 'number' ? { donationCost: of.donationCost / K } : {}),
          })),
        })
        const eBudget = Math.max(0, (richer.logM - plan.logM) / Math.log(K))
        const eRep = Math.max(0, (faster.logM - plan.logM) / Math.log(K))

        // Remaining windows to the exit condition, on the measured growth.
        const wdd = bitNodeMults(info?.currentNode)?.WorldDaemonDifficulty
        const needMult = wdd > 0 ? multiplierNeeded(3000 * wdd, player.exp?.hacking ?? 0) : null
        const g = joinState?.rateGrowthPerCycle
        const remainingWindows =
          needMult > (player.mults?.hacking ?? 0) && g > 1
            ? Math.log(needMult / player.mults.hacking) / Math.log(g)
            : null

        // The batcher's own saturation and thread shape, from its telemetry.
        const bt = readJson(ns, '/tel/batch.txt')
        const live = (bt?.targets ?? []).filter((t) => t?.plan && t.cal?.chanceObs != null)
        const chanceObs = live.length ? live.reduce((a, t) => a + t.cal.chanceObs, 0) / live.length : null
        const growShare = live.length
          ? live.reduce((a, t) => a + t.plan.g / (t.plan.h + t.plan.g + t.plan.w1 + t.plan.w2), 0) / live.length
          : null

        const derived = deriveWeights({
          remainingWindows,
          eBudget,
          eRep,
          hackingMult: player.mults?.hacking,
          level: player.skills?.hacking,
          chanceObs,
          growShare,
        })
        if (derived) {
          channelWeights = derived.weights
          // CHARISMA RIDES IN FROM THE PREVIOUS PASS. The desk probe runs in
          // planFactionWork (it needs the schedule's best rate) and persists
          // its channel weights in the schedule file; merging the prior
          // pass's figures here closes the loop with a 5-minute lag. The
          // channels list widens with them: charisma stays OUT of the flat
          // basket (weight-1 charisma would be a hand-tuned constant again),
          // and enters only priced.
          try {
            const priorSched = readJson(ns, SCHEDULE)
            if (priorSched?.chaWeights && priorSched.lastAugReset === info?.lastAugReset) {
              for (const [k, v] of Object.entries(priorSched.chaWeights)) {
                if (typeof v === 'number' && isFinite(v) && v > 0) {
                  channelWeights[k] = v
                  if (!channelsUsed.includes(k)) channelsUsed.push(k)
                }
              }
            }
          } catch {
            /* no prior probe — charisma stays unpriced this pass */
          }
          weightsMeta = { source: 'derived', eBudget: +eBudget.toFixed(4), eRep: +eRep.toFixed(4), remainingWindows: +(+remainingWindows).toFixed(1), weights: Object.fromEntries(Object.entries(channelWeights).map(([k, v]) => [k, +v.toFixed(4)])) }
          plan = planPurchases({
            ...planArgs,
            channelWeights,
            channels: channelsUsed,
            // The elasticity and the window count only exist on this branch;
            // they are what turns a dollar grant into ln without inventing a
            // coefficient.
            oneoff: { ...oneoffBase, eBudget, remainingWindows, weights: channelWeights, channels: channelsUsed },
          })
        }
      } catch {
        /* any failure keeps the flat plan — degraded loudly via weightsMeta */
      }
    }
    // A planner that silently fell back to a heuristic must say so, every pass.
    if (!plan.exact) did.push(`plan is APPROXIMATE: ${plan.approximation}`)
    for (const rgroup of plan.restricted) did.push(`plan restricted: ${rgroup.why} (${rgroup.group.join(' -> ')})`)
  } else {
    todo.push('Augmentation purchases need Source-File 4 — buy them in the Factions UI, MOST EXPENSIVE FIRST (money cost multiplies 1.9x per already-queued aug; reputation cost does not), and buy a prerequisite BEFORE the augmentation that needs it.')
  }



  // --- unjoined factions, priced across the join boundary --------------------
  //
  // The ranking above this line can only see JOINED factions, and that blinds
  // it to the top of the augmentation table: measured on 2026-09-14, the best
  // augmentation our two joined factions sell multiplies progress x1.28 while
  // BitRunners — one backdoor away — holds a x2.84. So every unjoined hack
  // faction is gathered here with the game's own invitation requirements
  // (getFactionInviteRequirements, Singularity.ts:730) and its augmentation
  // list, and joinplan.js forecasts hours-to-eligibility from measured rates.
  // factionplan.js then prices the wait into the same value walk as everything
  // else, so "grind NiteSec" and "BitRunners opens in 9h" compete in one
  // ranking instead of the second being invisible.
  //
  // FAVOUR AND REPUTATION PERSIST ACROSS MEMBERSHIP, so they are read for
  // unjoined factions too — a faction we left at high favour re-prices
  // accordingly, which is the rep-cap-and-return pattern.
  let candidates = []
  let joinState = null
  if (canJoin) {
    // Backdoor state from backdoor.js's own telemetry (0GB read) rather than
    // ns.getServer (2GB): C4 allows it because backdoor.js verifies against
    // the game (`backdoorInstalled`) before writing, and a stale file only
    // DELAYS pricing a faction as open, never opens a closed one.
    const bd = readJson(ns, '/tel/backdoor.txt')
    const backdoors = Object.fromEntries((bd?.done ?? []).map((h) => [h, true]))
    const serverLevels = {}
    for (const [host] of STORY_SERVERS) {
      try {
        serverLevels[host] = ns.getServerRequiredHackingLevel(host)
      } catch {
        /* unknown server stays absent, and joinplan refuses to forecast it */
      }
    }
    // Company reputation held at each megacorp — persisted state the forecast
    // must credit (rep survives quitting; only prestige clears it), and the
    // input the measured-rate loop differentiates. getCompanyRep answers 0 for
    // a company never worked, so calling it for all ten is safe.
    const companyReps = {}
    const companyFavors = {}
    for (const m of MEGACORPS) {
      try {
        companyReps[m.company] = sing.getCompanyRep(m.company)
        // Favour survives installs (Company.ts:77-80) and multiplies later
        // rep gain — the ladder that makes a long stint converge across
        // lives. Without it the forecast reads the same 22h every life while
        // the truth shrinks.
        companyFavors[m.company] = sing.getCompanyFavor(m.company)
      } catch {
        /* unreadable stays absent — joinplan refuses rather than assumes 0 */
      }
    }
    // Income for the join-money legs: script income plus the expected
    // contract stream. Absent (undefined) when both are zero, so joinplan
    // refuses a money wait rather than dividing by nothing.
    const joinIncome = (() => {
      const inc = ns.getTotalScriptIncome()
      const s = (isFinite(inc?.[0]) && inc[0] > 0 ? inc[0] : 0) || (isFinite(inc?.[1]) && inc[1] > 0 ? inc[1] : 0)
      const t = s + contractMoneyPerSec
      return t > 0 ? t : undefined
    })()
    joinState = {
      incomePerSec: joinIncome,
      hacking: player.skills?.hacking,
      hackingExp: player.exp?.hacking,
      hackingMult: player.mults?.hacking,
      // The formula-derived stand-in for the base rep rate on passes where
      // nothing has measured yet (trajectory.js explains the Four Sigma
      // abandonment this prevents). getSharePower is the game's own share
      // bonus term — share.js runs, so omitting it would under-rate factions
      // in exactly the direction that caused the spurious desk stint.
      // THE INSTALL WINDOW, measured from the lifetimes ledger this file
      // writes at every install. The fallback constants are the values
      // MEASURED on 2026-09-15 (median 1.72h over the last 10 lives; mult
      // growth 3.4%/install across ~15) — dated, and self-replacing as the
      // ledger fills. They exist so the very first lives after deploy price
      // ladders instead of refusing.
      ...measureWindow(ns),
      lifeAgeH: Math.max(0, (Date.now() - (info?.lastAugReset ?? Date.now())) / 3600000),
      // The donation terminal's inputs (favor.js's repLadder): the threshold,
      // the conversion multipliers, and the money side. Income is read here —
      // cheap, already referenced — because the schedule runs before the
      // futures section reads it for its own purposes.
      donateAt: favorNeededToDonate(1),
      donateRepMult: player.mults?.faction_rep,
      donateNodeMult: bitNodeMults(info?.currentNode)?.FactionWorkRepGain ?? null,
      donateIncome: (() => {
        const inc = ns.getTotalScriptIncome()
        return (isFinite(inc?.[0]) && inc[0] > 0 ? inc[0] : 0) || (isFinite(inc?.[1]) && inc[1] > 0 ? inc[1] : 0) || null
      })(),
      baseRepEstimate: estimateBaseRepPerSec({
        hacking: player.skills?.hacking,
        intelligence: player.skills?.intelligence ?? 0,
        factionRepMult: player.mults?.faction_rep,
        nodeWorkRepMult: bitNodeMults(info?.currentNode)?.FactionWorkRepGain ?? null,
        sharePower: ns.getSharePower(),
      }),
      money: ns.getServerMoneyAvailable('home'),
      augCount: installedCount.size,
      backdoors,
      serverLevels,
      // THE BODY, for the combat-stat and crime forecasts (bodyplan.js via
      // joinplan.js). ns.getPlayer already carries every input: the six
      // skills, their exp and level/exp multipliers, karma, kills, city. The
      // crime terms come from the verified BitNode table; an unknown node
      // yields null there and joinplan refuses the crime legs rather than
      // pricing them against BitNode 1 (CrimeSuccessRate is 1 in most nodes
      // and the refusal costs nothing there — it exists for the ones where
      // it is not). The gym rate is scaled by the hacknet-hash training
      // upgrade, which is 1 wherever hashes do not exist; read, not assumed.
      body: {
        skills: player.skills,
        exp: player.exp,
        mults: player.mults,
        karma: player.karma,
        numPeopleKilled: player.numPeopleKilled,
        city: player.city,
        money: ns.getServerMoneyAvailable('home'),
      },
      node: bitNodeMults(info?.currentNode) ?? null,
      trainingMult: ns.hacknet.getTrainingMult(),
      // The acting branch below commits crimes FOCUSED, so the model prices
      // the focused rate (CrimeWork.ts:65 focusPenalty = 1 when focused).
      focus: 1,
        hacknetSpend: (() => {
        try {
          const h = JSON.parse(ns.read('/tel/hacknet.txt') || 'null')
          // The life must match: nodes are wiped by every install, so a
          // `done` from a previous one describes a fleet that is gone.
          return h?.done === true && h?.lastAugReset === info?.lastAugReset ? 0 : undefined
        } catch {
          return undefined
        }
      })(),
      companyCtx: {
        hacking: player.skills?.hacking,
        charisma: player.skills?.charisma,
        // Growth happens in EXP space — the trajectory model needs the raw
        // exp and both charisma multipliers, not just the displayed level.
        chaExp: player.exp?.charisma,
        chaMult: player.mults?.charisma,
        chaExpMult: player.mults?.charisma_exp,
        // Leadership at ZB Institute (Volhaven): base 4 chaExp/cycle x 5
        // cycles/s / 5 gameCPS x location expMult 4 (LocationsMetadata.ts:422)
        // x charisma_exp. No BitNode term: ClassGymExpGain has NO consumer in
        // gameplay code — verified by grep on 2026-09-15, and worth
        // re-checking on a fork fast-forward.
        uniChaExpPerSec: 4 * 4 * (player.mults?.charisma_exp ?? 1),
        intelligence: player.skills?.intelligence ?? 0,
        companyRepMult: player.mults?.company_rep,
        // BN4 leaves CompanyWorkRepGain at 1, but read it from the verified
        // override table rather than assuming — this is the exact constant
        // family that sat silently wrong for a whole BitNode. An unknown node
        // yields null, which makes joinplan refuse company forecasts rather
        // than price them against BitNode 1.
        nodeCompanyRepMult: bitNodeMults(info?.currentNode)?.CompanyWorkRepGain ?? null,
        // The EXP-side BitNode term is a different key with a different value
        // (0.5 in BN4 where the rep term is 1) — conflating them halves or
        // doubles the charisma trajectory silently.
        nodeCompanyExpMult: bitNodeMults(info?.currentNode)?.CompanyWorkExpGain ?? null,
        // What Netburners' hacknet requirements would cost to finish, read
        // from hacknet.js's own report rather than priced here — pricing the
        // upgrade curve would mean six ns.hacknet references in this file for
        // a number the script that buys them already knows.
        //
        // Deliberately only two answers: 0 when it reports done, and ABSENT
        // otherwise, which makes joinplan refuse. This does not forecast "how
        // long until Netburners" — it says whether it is available now. That
        // is enough, because hacknet.js runs from boot.js's manifest whatever
        // the ranking thinks, so the requirement gets satisfied on its own and
        // the faction becomes priceable the moment it is genuinely true. Not circular:
        // nothing gates hacknet.js's launch on this file.
        jobs: player.jobs ?? {},
        repByCompany: companyReps,
        favorByCompany: companyFavors,
        measuredRates: {}, // filled by planFactionWork from its prior sample
      },
    }
    // EVERY FACTION IS A CANDIDATE. This used to be
    // `[...HACK_FACTIONS, ...MEGACORPS.map((m) => m.faction)]` — 18 of the 34
    // real factions — and the other 16 were not ranked badly, they were
    // INVISIBLE: absent from `joinForecasts` AND from `unpriceable`, so no
    // telemetry anywhere recorded that they had been skipped.
    //
    // Measured cost, in BitNode 1 with the run nine distinct augmentations
    // short of Daedalus and the hacking multiplier already past the exit bar:
    // the schedule was grinding 1,138,561 reputation at ECorp, budgeted at 5.8
    // hours, for multipliers the run no longer needed — while Tian Di Hui's
    // eight augmentations sat behind 138,750 reputation and Netburners' five
    // behind 28,125, about twenty minutes at the rate in that same plan. Its
    // own Daedalus forecast said the augmentation count was 92.5 HOURS away.
    //
    // The city factions still route through bestCompatibleSet below, because
    // joining one BANS the incompatible rest and that is a set decision rather
    // than a per-faction one. They are priced here all the same: an unjoinable
    // faction fails on its requirements, which is a measured refusal and is
    // reported, where an omission is not.
    for (const name of ALL_FACTIONS) {
      if (player.factions.includes(name)) continue
      try {
        const augs = []
        for (const aug of sing.getAugmentationsFromFaction(name)) {
          if (allCount.has(aug) && aug !== NFG) continue
          augs.push({ name: aug, repReq: sing.getAugmentationRepReq(aug), mults: sing.getAugmentationStats(aug) })
        }
        candidates.push({
          name,
          requirements: sing.getFactionInviteRequirements(name),
          augs,
          rep: sing.getFactionRep(name),
          favor: sing.getFactionFavor(name),
        })
      } catch (e) {
        // An unreadable faction is REPORTED, not dropped — a silently missing
        // candidate is exactly how the join boundary was invisible before.
        todo.push(`could not price unjoined faction ${name}: ${String(e).slice(0, 80)}`)
      }
    }
  }

  // Computed ONCE, above the branch, because both the condition ("are we
  // working the wrong faction?") and the body ("which one should we start?")
  // need the same answer. Computing it twice would also write the telemetry
  // twice and could disagree with itself between the two reads.
  const schedule = canJoin && (factions?.length || candidates.length) ? planFactionWork(ns, sing, factions ?? [], offers, info, { candidates, state: joinState, channelWeights, channels: channelsUsed, weightsMeta }) : null
  let scheduleTarget = schedule?.current?.faction ?? null
  // THE GANG FACTION FIRST, in a node that allows a gang. Its catalogue
  // grows to almost every augmentation in the game once the gang exists, so
  // its join outranks any augmentation walk priced on today's catalogue —
  // a comparison the ranking cannot make, because the value it would need
  // is the one the gang creates. Take the cheapest gang faction to join,
  // by joinplan's own forecast, and hand it to the body step below as the
  // current segment. gang.js creates the gang the moment the join lands.
  if (canJoin && canUseGang(info) && !ns.gang.inGang() && !player.factions.some((f) => GANG_FACTIONS.includes(f))) {
    const pick = (schedule?.joinForecasts ?? [])
      .filter((f) => GANG_FACTIONS.includes(f.name) && typeof f.hours === 'number' && isFinite(f.hours))
      .sort((a, b) => a.hours - b.hours)[0]
    if (pick) {
      scheduleTarget = pick.name
      if (schedule) schedule.current = { faction: pick.name, workH: Math.max(pick.activeHours ?? 0, 1e-6), hours: pick.hours, gangFaction: true }
      did.push(`gang node: targeting ${pick.name} first (${(pick.hours * 60).toFixed(1)} min to its invitation) — its catalogue becomes the augmentation ladder once the gang exists`)
    } else {
      todo.push(`gang node, but no gang faction is priceable yet: ${(schedule?.unpriceable ?? []).filter((u) => GANG_FACTIONS.includes(u.name)).map((u) => u.name).join(', ') || 'none listed'}`)
    }
  }

  // COMPANY WORK, when the schedule says the best segment BEGINS with it.
  // `workH` on the current segment means "this faction is entered through
  // employment" — the megacorp path — and the instruction is to sit at the
  // company's desk, not to grind a faction we are not in. applyToCompany is
  // called every pass while this holds: it hires on the first pass and
  // PROMOTES on later ones the moment a reputation threshold is crossed
  // (Singularity.ts applies for the best qualifying position), which is what
  // makes companyplan.js's ladder walk real rather than aspirational.
  const wantCompany =
    schedule?.current?.workH > 0 ? (MEGACORPS.find((m) => m.faction === schedule.current.faction)?.company ?? null) : null
  // Starting employment is deferred until the ranking is MEASURED, not
  // estimated: a stint begun off formula-only rates is how the Four Sigma
  // desk got started and abandoned inside one measuring interval. Five
  // minutes of deferral against a 20h stint is free; work already underway
  // is left alone (abandoning mid-stint is the ranking's call, not this
  // guard's).
  // THE TRAVEL STEP, for a faction whose only unmet requirement is WHERE WE
  // ARE STANDING. joinplan prices a `city` requirement at zero hours because
  // Singularity.travelToCity does no work and charges a flat $200k
  // (Singularity.ts:375-393) — but a price is not a plan unless something
  // performs it. Without this, the schedule ranks Tian Di Hui first at rate
  // 9.3741 (three times the next segment) and then waits forever for an
  // invitation that only arrives once the player is in Chongqing, New Tokyo or
  // Ishima. Priced-but-unactionable is the same family of bug as the desk
  // guard that deferred work and so never measured the rate it was waiting on.
  //
  // Only for the faction the schedule actually CHOSE, and only when its own
  // forecast named the destination — never a speculative tour of the map.
  if (canJoin && !flags.dry && scheduleTarget) {
    const want = schedule?.joinForecasts?.find((f) => f.name === scheduleTarget)
    const dest = want?.blockers?.find((b) => b.travel)?.travel?.city
    if (dest && player.city !== dest && !player.factions.includes(scheduleTarget)) {
      try {
        if (sing.travelToCity(dest)) {
          did.push(`travelled to ${dest} for the ${scheduleTarget} invitation (its only unmet requirement was location; $200k, no time)`)
        } else {
          todo.push(`could not travel to ${dest} for ${scheduleTarget} — needs $200k on hand`)
        }
      } catch (e) {
        todo.push(`travel to ${dest} failed: ${String(e).slice(0, 60)}`)
      }
    }
  }

  // THE WORK SLOT, PRICED. An hour of the best money crime is worth
  // moneyLn(dollars/h) in the same ln(M) the schedule prices an hour of
  // faction work in (schedule.current.rate). Whichever is larger gets the
  // slot; a refusal (no measured elasticity yet) leaves faction work in
  // place and says why. Crime money was computed by bodyplan and consumed by
  // nothing until 2026-09-19 — in BitNode 2, where crime pays x3, the
  // early-game truth was Mug at $33k/s against a fleet earning $108/s.
  const crimeAlt = (() => {
    if (!joinState?.body || !joinState?.node) return null
    const c = bestCrimeFor('money', joinState.body, joinState.node, { focus: 1 })
    if (!c) return null
    const perHour = c.rates.money * 3600
    const rate = schedule?.current?.rate
    const v = moneyLn(perHour, { money: player.money, eBudget: weightsMeta?.eBudget, remainingWindows: weightsMeta?.remainingWindows })
    if (v.ln === null) return { crime: c.crime, perHour, wins: false, why: v.reason }
    if (!(rate > 0)) return { crime: c.crime, perHour, lnPerHour: v.ln, wins: true, why: 'no priced faction work to compete with' }
    return { crime: c.crime, perHour, lnPerHour: v.ln, factionLnPerHour: rate, wins: v.ln > rate, why: v.ln > rate ? `crime ${v.ln.toFixed(4)} > faction ${rate.toFixed(4)} ln(M)/h` : `faction ${rate.toFixed(4)} >= crime ${v.ln.toFixed(4)} ln(M)/h` }
  })()
  const alreadyAtDesk = work?.type === 'COMPANY' && work.companyName === wantCompany
  const deskGuarded = wantCompany && schedule?.estimated && !alreadyAtDesk

  // THE BODY STEP: the schedule chose a faction whose invitation needs crime
  // (karma, kills) or a gym (combat stats). Same family as the Leadership
  // step — joinplan priced it, so something has to perform it or the price
  // is fiction. Crime first, because the leg was priced with the crimes'
  // combat exp credited to the gym; then each stat still short, one class at
  // a time, at the gym the forecast named.
  const bodyStep = (() => {
    if (!scheduleTarget || wantCompany || !(schedule?.current?.workH > 0)) return null
    if (player.factions.includes(scheduleTarget)) return null
    const f = schedule?.joinForecasts?.find((x) => x.name === scheduleTarget)
    const crime = f?.blockers?.find((b) => b.crime)?.crime
    if (crime && !crime.why) {
      const karmaShort = typeof crime.karma === 'number' && player.karma > crime.karma
      const killsShort = typeof crime.kills === 'number' && player.numPeopleKilled < crime.kills
      if (karmaShort || killsShort) return { kind: 'crime', type: crime.type, hours: crime.hours, karmaShort, killsShort }
    }
    const gym = f?.blockers?.find((b) => b.gym)?.gym
    const leg = gym?.legs?.find((l) => (player.skills?.[l.stat] ?? 0) < l.to)
    if (gym && !gym.why && leg) return { kind: 'gym', gym: gym.gym, city: gym.city, ...leg }
    return null
  })()

  // WHICH FACTION THE NEXT SAMPLE BELONGS TO.
  //
  // planFactionWork records `workingFaction` so the next pass knows which
  // reputation delta is the measurement — and it recorded the faction the PLAN
  // wanted, which is not always the one we work. Live, the plan said ECorp (a
  // faction we have not joined, reached through employment) while the desk
  // guard had us working BitRunners: next pass looked up reps['ECorp'], found
  // nothing, left the base rate null, and so stayed `estimated` — which is the
  // very condition the guard defers on. The measurement the guard was waiting
  // for was being taken and thrown away every pass.
  //
  // Default to whatever is already running, because an untouched grind is
  // still the faction accruing reputation; the branches below overwrite it
  // when they change the answer.
  let workedFaction = work?.type === 'FACTION' ? (work.factionName ?? null) : null

  if (deskGuarded) {
    // DEFER THE DESK, NOT THE WORK SLOT. This branch used to be terminal,
    // which deadlocked the whole system: deferring the desk started nothing
    // else, so no reputation moved, so the base rate never measured, so the
    // ranking stayed `estimated`, so the desk stayed deferred — the work
    // slot sat at None indefinitely (observed live: income $81B/s, a $45T
    // plan pending, and current work: None). Falling through to faction work
    // produces the very measurement the guard is waiting for, and the desk
    // starts one pass later on a measured ranking.
    todo.push(`${wantCompany} desk stint deferred one pass — the ranking that chose it is estimated; working a faction meanwhile to measure it`)
  }
  if (bodyStep && canWork && !flags.dry) {
    workedFaction = null
    if (bodyStep.kind === 'crime') {
      const already = work?.type === 'CRIME' && String(work.crimeType ?? '') === bodyStep.type
      if (!already) {
        try {
          // commitCrime returns the crime's duration in ms and starts ONE
          // attempt; the game repeats it (CrimeWork.process loops) until the
          // work is replaced, so this is a start, not a per-attempt call.
          const ms = sing.commitCrime(bodyStep.type, true)
          if (ms > 0) did.push(`committing ${bodyStep.type} (~${bodyStep.hours.toFixed(2)}h) for the ${scheduleTarget} invitation — ${bodyStep.karmaShort ? 'karma' : 'kills'} short`)
          else todo.push(`commitCrime(${bodyStep.type}) did not start`)
        } catch (e) {
          todo.push(`crime step failed: ${String(e).slice(0, 80)}`)
        }
      }
    } else {
      const cls = GYM_CLASS[bodyStep.stat]
      const already = work?.type === 'CLASS' && String(work.classType ?? '') === cls && work.location === bodyStep.gym
      if (!already) {
        try {
          if (player.city !== bodyStep.city) sing.travelToCity(bodyStep.city)
          if (sing.gymWorkout(bodyStep.gym, cls, true)) {
            did.push(`training ${bodyStep.stat} to ${bodyStep.to} at ${bodyStep.gym} (~${bodyStep.hours.toFixed(2)}h) for the ${scheduleTarget} invitation`)
          } else {
            todo.push(`gymWorkout(${bodyStep.gym}, ${cls}) refused — in ${player.city}, needs ${bodyStep.city}`)
          }
        } catch (e) {
          todo.push(`gym step failed: ${String(e).slice(0, 80)}`)
        }
      }
    }
  } else if (!deskGuarded && wantCompany && canWork && !flags.dry) {
    // THE TRAINING STEP, when the forecast priced it in. joinplan's blocker
    // carries `train: {toCha, hours}` ONLY when front-loading Leadership study
    // beat the plain stint on total hours — so this branch fires exactly when
    // the arithmetic says studying first is faster, and stops firing the pass
    // charisma crosses the bar. No threshold constant to go stale: the
    // trajectory model re-decides every pass as favour banks and augs land.
    const forecast = schedule?.joinForecasts?.find((f) => f.name === schedule.current.faction)
    const train = forecast?.blockers?.find((b) => b.train)?.train
    // Either arm of this branch — the desk or the classroom — displaces
    // faction work, so no faction reputation accrues until the next pass.
    workedFaction = null
    if (train && (player.skills?.charisma ?? 0) < train.toCha) {
      const studying = work?.type === 'CLASS' && String(work.classType ?? '') === 'Leadership'
      if (!studying) {
        // ZB Institute is the x4 campus and it is in Volhaven; the class API
        // requires being in the university's city (Singularity.ts checks
        // Player.city per campus). Travel is instant and $200k — seconds of
        // income against the hours the better campus saves.
        try {
          if (player.city !== 'Volhaven') sing.travelToCity('Volhaven')
          if (sing.universityCourse('ZB Institute of Technology', 'Leadership', true)) {
            did.push(`studying Leadership at ZB to charisma ${train.toCha} (~${train.hours.toFixed(1)}h) before the ${wantCompany} desk — training beat the plain stint on total hours`)
          } else {
            todo.push(`Could not start the Leadership course at ZB — start it manually (Volhaven > ZB Institute).`)
          }
        } catch (e) {
          todo.push(`Training step failed: ${String(e).slice(0, 80)}`)
        }
      }
    } else {
      const already = work?.type === 'COMPANY' && work.companyName === wantCompany
      try {
        const position = sing.applyToCompany(wantCompany, 'Software')
        if (position) did.push(`applied at ${wantCompany}: now ${typeof position === 'string' ? position : 'hired'}`)
      } catch {
        /* not qualified for a promotion right now — the current job stands */
      }
      if (!already) {
        if (sing.workForCompany(wantCompany, true)) {
          did.push(`working at ${wantCompany} (company) toward the ${schedule.current.faction} faction — ${schedule.current.workH.toFixed(1)}h of employment in the plan`)
        } else {
          todo.push(`Could not start company work at ${wantCompany} — apply and start it manually (City > ${wantCompany}).`)
        }
      }
    }
  } else if (deskGuarded && factions?.length && canWork && !flags.dry) {
    // The measuring fallback. Any joined faction's work feeds the rate
    // measurement, so this branch's freedom is in WHICH — and the first
    // version spent it on HACK_FACTIONS order, the same hand-ranked list the
    // comment below documents as a 21x pricing error. Live, that ground
    // BitRunners: zero unowned augmentations left in its catalogue and
    // favour 465, so every second bought literally nothing, while Sector-12
    // sat 1,220 reputation short of the first of four augmentations that
    // complete the Daedalus count.
    //
    // The ordering rule is that reputation which can be BOUGHT should not be
    // WORKED. Past the donation threshold, money converts to reputation
    // directly (donation.ts:8) and an hour of grinding is dominated by an
    // instant at $81B/s income; below it, work is the only channel there is.
    // So the fallback prefers a faction that still owes us an augmentation
    // AND cannot be donated to, nearest unlock first.
    const fallback = measuringTarget(sing, factions, offers, info)
    if (!(work?.type === 'FACTION' && work.factionName === fallback)) {
      if (sing.workForFaction(fallback, 'hacking', true)) did.push(`working ${fallback} while the desk ranking measures`)
    }
    workedFaction = fallback
  } else if (!factions || factions.length === 0) {
    if (wantCompany) {
      todo.push(`Best plan starts with employment at ${wantCompany} — needs Singularity to act.`)
    } else {
      todo.push('NO FACTION JOINED — reputation is earning ZERO. Backdoor a story server (run findpath.js <server>) and accept the invite.')
    }
  } else if (!work || work.type !== 'FACTION' || wrongFaction(sing, work, factions, canJoin, scheduleTarget) || (crimeAlt?.wins && work.type !== 'CRIME')) {
    // ALSO RE-EVALUATE WHILE ALREADY WORKING.
    //
    // This branch used to fire only when no faction work was running, so
    // whichever faction was picked first was ground forever. Live, that meant
    // NiteSec (432,793 reputation from the donation threshold) kept being
    // worked while CyberSec sat 110,783 closer — the choice was made once,
    // under a ranking that is wrong before donations unlock, and never revisited.
    //
    // Switching costs nothing: reputation already earned is banked per faction
    // and does not decay, so changing target only changes which faction the
    // NEXT second accrues to. The target is a deterministic function of the
    // favour gap, so it cannot oscillate unless two factions are within a
    // rounding error of each other — and then either is equally good.
    // WHICH FACTION TO WORK — priced, not listed.
    //
    // HACK_FACTIONS is a hand-ordered preference. It encodes one true fact
    // (Daedalus sells better augmentations than CyberSec) and then answers a
    // different question with it: where is an hour of work worth most RIGHT
    // NOW? Live, it ground NiteSec at 0.0455 ln(M)/h while CyberSec paid
    // 0.9588 — a 21x error, because NiteSec ranks higher in the list.
    //
    // factionplan.js prices each faction as the multiplier its LOCKED
    // augmentations would add, over the time to earn the reputation that
    // releases them, with favour applied to the rate (reputation.ts:9). It also
    // returns a SCHEDULE — work to a reputation cap, switch, come back — which
    // is what makes "hit the cap and move on" expressible rather than emergent.
    const byQuality = HACK_FACTIONS.find((f) => factions.includes(f)) ?? factions[0]
    const target = scheduleTarget ?? byQuality
    if (schedule?.current) {
      did.push(
        `plan: ${schedule.segments.map((g) => `${g.faction}->${Math.round(g.untilRep).toLocaleString()}rep(${g.hours.toFixed(1)}h)`).join(' ')}`,
      )
    }
    if (canWork && !flags.dry && crimeAlt?.wins) {
      workedFaction = null
      if (work?.type === 'CRIME' && String(work.crimeType ?? '') === crimeAlt.crime) {
        did.push(`crime loop (${crimeAlt.crime}) holds the work slot: ${crimeAlt.why}`)
      } else if (sing.commitCrime(crimeAlt.crime, true) > 0) {
        did.push(`committing ${crimeAlt.crime} for money (${Math.round(crimeAlt.perHour / 3600)}/s): ${crimeAlt.why}`)
      } else todo.push(`commitCrime(${crimeAlt.crime}) did not start`)
    } else if (canWork && !flags.dry) {
      if (sing.workForFaction(target, 'hacking', true)) {
        did.push(`working for ${target}, focused${crimeAlt ? ` (${crimeAlt.why})` : ''}`)
        workedFaction = target
      } else todo.push(`Could not start faction work for ${target} — start it manually.`)
    } else {
      todo.push(`NO FACTION WORK RUNNING — reputation is earning ZERO. Start hacking contracts for ${target} and FOCUS it (unfocused costs 20%).`)
    }
  } else if (canWork && !sing.isFocused()) {
    if (canWork && !flags.dry) {
      sing.setFocus(true)
      did.push('refocused faction work')
    } else {
      todo.push('Faction work is UNFOCUSED — costs 20% of the rate. Click Focus, then verify a few seconds later; it has been seen reverting.')
    }
  }

  // Correct the schedule's record to the faction actually being worked. Done
  // here rather than inside planFactionWork because the work decision is made
  // after the plan is written, and a measurement labelled with the wrong
  // faction is worse than no measurement: it reads as a real zero.
  if (schedule && workedFaction !== schedule.workingFaction) {
    schedule.workingFaction = workedFaction
    ns.write(SCHEDULE, JSON.stringify(schedule, null, 2), 'w')
  }

  // --- 3. port programs ------------------------------------------------------
  // Each one unlocks a tier of servers to root, and rooting is gated on open
  // ports alone, never on hacking level — so they are worth buying the moment
  // they are affordable, at any level.
  const PROGRAMS = [
    ['BruteSSH.exe', 500e3],
    ['FTPCrack.exe', 1.5e6],
    ['relaySMTP.exe', 5e6],
    ['HTTPWorm.exe', 30e6],
    ['SQLInject.exe', 250e6],
  ]
  // The game's own predicate; serverExists('darkweb') is always true.
  const hasTor = ns.hasTorRouter()
  if (!hasTor) {
    if (canJoin && !flags.dry && ns.getServerMoneyAvailable('home') > 200e3) {
      if (sing.purchaseTor()) did.push('bought TOR')
    } else todo.push('Buy the TOR router ($200k) — gates every port program.')
  }
  for (const [file, price] of PROGRAMS) {
    if (ns.fileExists(file, 'home')) continue
    if (canJoin && !flags.dry && ns.getServerMoneyAvailable('home') > price * 2) {
      if (sing.purchaseProgram(file)) did.push(`bought ${file}`)
    } else if (ns.getServerMoneyAvailable('home') > price) {
      todo.push(`Buy ${file} ($${(price / 1e6).toFixed(1)}m) — unlocks a tier of servers to root.`)
    }
  }

  // --- 4. PLAN the augmentations; do not buy yet -----------------------------
  //
  // THE CHANGE. The shipped loop sorted `offers` by price descending and bought
  // whatever was affordable on THIS pass. Three defects, all of them silent:
  //
  //   (i)  it bought ACROSS TIME rather than planning a set. The k-th purchase
  //        of an install cycle costs `intrinsic * 1.9^k`
  //        (AugmentationHelpers.ts:32-37,157), so rank 0 is the most valuable
  //        position there is — and a five-minute pass spent it on whatever
  //        happened to be affordable at the time.
  //   (ii) it ranked by PRICE, not by VALUE. On the real BitNode 4 catalogue
  //        that buys Neuralstimulator at $3,000m — hacking_chance, hacking_speed
  //        and hacking_grow, none of which appear in installgate.js's
  //        RATE_CHANNELS — at rank 0, for a multiplier gain of exactly zero.
  //        Measured: tools/staging/augplan/measure.mjs.
  //   (iii) it ignored prerequisites. `purchaseAugmentation` returns false when
  //        a prereq is unmet (FactionHelpers.tsx:88-95) and the loop moves on,
  //        so an augmentation we have the reputation and the money for is simply
  //        never bought and nothing says so.
  //
  // augplan.js owns the economics now, exactly as installgate.js owns the
  // install decision. This section only gathers what it needs.
  //
  // PRICES ARE LIVE, NOT BASE. getAugmentationPrice has already applied
  // 1.9^(queued non-SoA) and the BitNode multiplier. With the plan-now-buy-later
  // architecture nothing is queued at plan time, so the live price IS the rank-0
  // intrinsic — but not on the first pass after a deploy, or after a partially
  // executed plan. So the queued count is measured and divided back out, and
  // `nodeMoneyMult` is left at 1 because the live price already carries it.
  // --- 5. the gate, then execute the plan and install ------------------------
  //
  // THE CHICKEN AND EGG, and its fix.
  //
  // installgate.js decides on `M` over the QUEUED augmentations. Move purchasing
  // to "plan now, buy at install time" and nothing is ever queued, so M is always
  // 1, `shouldInstall` returns "the queued augmentations give no gain", and the
  // gate NEVER FIRES. The run would then accumulate money forever and never
  // install — which in a node whose exit is multiplier-bound is the single worst
  // failure mode available (installgate.js, "a gate that refuses to install is
  // not conservative — it is the failure mode").
  //
  // The fix is to evaluate the PLANNED set rather than the queued set. That is
  // strictly better than the old behaviour, not merely equivalent:
  //
  //   - it is forward-looking. The gate sees what the money COULD buy, including
  //     a threshold reputation has just crossed, before a dollar is committed.
  //   - the marginal-versus-average rule is unchanged. Planned M rises for
  //     exactly the reasons queued M used to rise (money accumulating,
  //     reputation crossing requirements) and flattens for exactly the reasons
  //     it used to flatten — so `d ln(M)/dt < ln(M)/A` still means "accumulation
  //     has stalled, cash in".
  //   - it removes the reason the old loop was wrong. Nothing is bought
  //     opportunistically at minute 5 and then repriced at 1.9x for everything
  //     that follows.
  //
  // M IS THE PRODUCT OF BOTH SETS. Anything already queued from a previous pass
  // (or from a partially executed plan) will also be installed, so it counts —
  // planned M alone would under-report and the gate would hold on a queue it
  // should be cashing in.
  //
  // THE THRASH GUARD STILL HOLDS, for a different reason than before.
  // installgate.js's header argues the gate cannot fire twice in a row because
  // an install sets money to $1,262 (PlayerObjectGeneralMethods.ts:102) and M is
  // therefore 1. Under this change the argument becomes "nothing is affordable
  // at $1,262, so the PLAN is empty and M is 1". That is still true, but it is
  // now a property of the planner rather than of the queue — so it is asserted
  // in tools/staging/augplan/augplan.test.mjs [AP9] instead of left as prose.
  const count = (list) => list.reduce((m, a) => m.set(a, (m.get(a) ?? 0) + 1), new Map())
  let pending = []
  if (canBuyAug) {
    // MULTISET difference, not a Set difference. getOwnedAugmentations(true)
    // returns installed names CONCATENATED with queued names, duplicates
    // included (Singularity.ts:79-90). NeuroFlux Governor is stackable, so with
    // a Set every queued NeuroFlux was discarded — four of them (M = 1.1268)
    // reported as M = 1.0000, and the gate held on evidence it should have
    // counted.
    const installed = count(sing.getOwnedAugmentations(false))
    for (const [name, n] of count(sing.getOwnedAugmentations(true))) {
      for (let i = 0; i < n - (installed.get(name) ?? 0); i++) pending.push(name)
    }
  }

  // THE SAME OBJECTIVE THE PLAN USES. This called progressFactor with no
  // channels and no weights — the FLAT basket — while plan.M below is priced
  // on the DERIVED weights, and the next line multiplies the two together and
  // hands the product to the install gate as one number. Two different
  // objectives in one product, feeding rho, the lifetimes ledger and every
  // install decision. Nothing complained, because each half was correct on its
  // own; only the composition was not. Now both sides ask objective.js.
  //
  // `real` and not `ln`: this is a REPORTED multiplier, so it must carry no
  // synthetic dominance value — that is the split augValue exists to keep.
  const heldM = pending.reduce(
    (m, a) => m * Math.exp(augValue({ name: a, mults: sing.getAugmentationStats(a) }, { channels: channelsUsed, weights: channelWeights }).real),
    1,
  )
  const M = heldM * (plan ? plan.M : 1)
  const total = pending.length + (plan ? plan.buy.length : 0)

  // PUBLISH EVEN WHEN THERE IS NOTHING TO BUY.
  //
  // budget.js's spenders read this file to learn what money is already
  // promised, and its rule is that an unreadable claim blocks spending. If this
  // file only appeared when a plan existed, then "nothing planned" and
  // "progress.js is dead" would be the same observation — absence — and every
  // spender would have to guess which. Writing `planned: false` makes the empty
  // case a POSITIVE statement, so a missing file can mean exactly one thing:
  // the publisher is not running, which is when spending should stop.
  // The wd-readiness line must survive an empty queue: the final life can
  // have nothing left to buy, and THAT is exactly when the human's click is
  // the only remaining step. (The full sprint arithmetic lives in the
  // planned path; this is the minimal always-on echo.)
  if (total === 0 && installedCount.has('The Red Pill')) {
    try {
      const wdReq = ns.getServerRequiredHackingLevel('w0r1d_d43m0n')
      todo.push(
        (player.skills?.hacking ?? 0) >= wdReq
          ? `W0R1D_D43M0N IS READY: hacking ${player.skills.hacking} >= ${wdReq}. Run findpath.js w0r1d_d43m0n, connect, and backdoor it YOURSELF — cmd.js refuses wd by design.`
          : `Red Pill installed — hacking ${player.skills?.hacking} of ${wdReq} for the final backdoor.`,
      )
    } catch {
      /* server not spawned yet */
    }
  }

  if (total === 0) {
    // The income sample rides EVERY pass, planned or not. It used to live only
    // on the planned path, so a fresh life — nothing affordable yet — never
    // started the calibration loop, and the first scoreable prediction was
    // deferred to whenever augmentations happened to become buyable.
    const inc0 = ns.getTotalScriptIncome()
    const incNow = (isFinite(inc0?.[0]) && inc0[0] > 0 ? inc0[0] : 0) || (isFinite(inc0?.[1]) && inc0[1] > 0 ? inc0[1] : 0)
    let prevIncome0 = null
    try {
      const saved = JSON.parse(ns.read(GATE) || 'null')
      if (saved?.incomeSample && saved.lastAugReset === info?.lastAugReset) prevIncome0 = saved.incomeSample
    } catch {
      /* absent or mid-write — no prior, which only defers scoring */
    }
    ns.write(
      GATE,
      JSON.stringify(
        {
          at: new Date().toISOString(),
          lastAugReset: info?.lastAugReset,
          planned: false,
          pending: [],
          plan: null,
          joinClaim: joinMoneyClaim(candidates, player),
          incomeSample: makeIncomeSample(incNow, player, schedule),
          incomeCalibration: scoreIncome(prevIncome0, incNow),
        },
        null,
        2,
      ),
      'w',
    )
  }

  if (total > 0) {
    // installgate.js owns the decision. The rule is marginal-versus-average on
    // ln(M)/A, so it needs the PREVIOUS sample — which means this file has to
    // persist one between runs. progress.js is a job: it exits after every
    // pass, so nothing survives in memory.
    let prev = null
    let prevIncome = null
    let prevFutures = []
    let prevCalSamples = []
    try {
      const saved = JSON.parse(ns.read(GATE) || 'null')
      // Only a sample from THIS life is meaningful. lastAugReset moves on every
      // install, so a sample whose age exceeds ours belongs to a previous life
      // and would make the marginal rate nonsense.
      if (saved && saved.sample && saved.lastAugReset === info?.lastAugReset) prev = saved.sample
      if (saved && saved.incomeSample && saved.lastAugReset === info?.lastAugReset) prevIncome = saved.incomeSample
      // The projections the LAST pass published, so this pass can score what
      // they actually delivered. Same staleness rule: a projection made in a
      // previous life was priced against a fleet and a reputation that no
      // longer exist.
      if (saved && Array.isArray(saved.futurePredictions) && saved.lastAugReset === info?.lastAugReset) {
        prevFutures = saved.futurePredictions
      }
      if (saved?.futuresCalibration && Array.isArray(saved.futuresCalibration.samples) && saved.lastAugReset === info?.lastAugReset) {
        prevCalSamples = saved.futuresCalibration.samples
      }
    } catch {
      /* absent or mid-write; treated as no previous sample, which only defers */
    }

    // WHAT WAITING WOULD BUY. The gate's rule needs a forward view, and
    // augplan.js can price one: re-plan against a budget projected forward by
    // income AND a reputation projected forward by the trajectory.
    //
    // Reputation used to be held still here, and that blindness is not
    // hypothetical: the $6.37b install destroyed its cash against a BINDING
    // REPUTATION constraint (13,231 needed, 3,089 held) that the futures
    // could not see, precisely because only money moved in the projection.
    // Now the faction the schedule is working has its rep advanced along the
    // same closed-form trajectory the schedule itself prices with, so a
    // rep-gated augmentation an hour away makes waiting win — the direction
    // that stops stranding cash.
    // INCOME, and why the obvious element is the wrong one to trust alone.
    //
    // getTotalScriptIncome returns two numbers (NetscriptFunctions.ts:1240):
    //   [0] sums onlineMoneyMade/onlineRunningTime over scripts running RIGHT NOW
    //   [1] is scriptProdSinceLastAug / playtimeSinceLastAug — an average
    //
    // [0] is instantaneous and so tracks the current fleet, but it counts only
    // processes alive at the sampling instant. Our earners are short-lived
    // batch workers, so a batch.js that has just been restarted contributes
    // nothing and [0] reads 0 — measured live at 23:32 on 2026-09-14 while the
    // game was genuinely earning $20.6k/s, then 20,928 eight minutes later.
    //
    // A ZERO HERE IS NOT HARMLESS. It skips the futures loop entirely, so
    // `waitBeats` is false, so the gate installs immediately — and it does that
    // precisely when it knows least. That is the "unguarded against waiting"
    // failure in the direction that strands cash.
    //
    // So fall back to the average, which is stable, and make the no-income case
    // a POSITIVE statement rather than an empty `futures` array that reads
    // identically to "waiting was considered and bought nothing".
    const income = ns.getTotalScriptIncome()
    const incomeNow = isFinite(income?.[0]) && income[0] > 0 ? income[0] : 0
    const incomeAvg = isFinite(income?.[1]) && income[1] > 0 ? income[1] : 0
    const incomePerSec = incomeNow || incomeAvg
    const incomeSource = incomeNow ? 'running-scripts' : incomeAvg ? 'since-last-aug' : 'none'
    let futures = []
    let incomeCalibration = null
    let futuresCalibration = null
    let futurePredictions = []
    if (plan && incomePerSec > 0) {
      // Rebuild the schedule's own trajectory from its persisted inputs — the
      // same calibrated closed form, so the gate and the schedule cannot
      // disagree about what an hour of grinding earns. Unavailable (no
      // measurements yet) degrades to money-only projection, the old answer.
      const workingF = schedule?.workingFaction ?? null
      const ftraj =
        workingF && schedule
          ? repModel({
              baseRepPerSec: schedule.measuredBaseRepPerSec,
              hacking: player.skills?.hacking,
              hackingExp: schedule.hackingExp,
              hackingMult: player.mults?.hacking,
              expPerSec: schedule.expPerSec,
            })
          : null
      const favMult = 1 + (canJoin && workingF ? Math.max(0, sing.getFactionFavor(workingF)) : 0) / 100
      // INCOME IS A TRAJECTORY TOO — the batch cycle is clocked by weaken
      // time, which divides by (hacking + 50), so income scales at least with
      // (level + 50) as the level climbs. trajectory.js states why that is a
      // LOWER bound (fleet growth and retargeting add more); the flat model
      // is the explicit fallback when the inputs are unmeasured.
      const itraj = incomeModel({
        incomePerSec,
        hacking: player.skills?.hacking,
        hackingExp: schedule?.hackingExp,
        hackingMult: player.mults?.hacking,
        expPerSec: schedule?.expPerSec,
      })
      // Two kinds of candidate. The FIXED ladder projects the working
      // faction's rep along its trajectory — ordinary waiting. The HOLD
      // candidates come from the schedule's spanning segments: each one says
      // "holdH continuous hours reach repTarget at this faction", the
      // alternative the install-window model priced but could not decide on.
      // Offering them here is what completes the separation of powers — the
      // schedule prices the options, the gate's marginal-rate rule chooses.
      const holds = holdCandidates(schedule?.segments)
      const candidates = [
        ...[0.25, 0.5, 1, 2, 4].map((waitH) => ({ waitH })),
        ...holds.map((h) => ({ waitH: h.holdH, hold: h })),
      ]
      for (const cand of candidates) {
        const { waitH, hold } = cand
        const waitMs = waitH * 3600000
        try {
          const repGain = ftraj ? ftraj.repBetween(0, waitH, favMult) : 0
          const moneyGain = itraj ? itraj.moneyBy(waitH) : incomePerSec * waitH * 3600
          const f = planPurchases({
            // Advance the worked faction along its trajectory; a hold
            // additionally lifts ITS faction to the target the continuous
            // grind reaches — that is the hold's entire point.
            offers: offers.map((o) => {
              let rep = o.factionRep
              if (repGain > 0 && o.faction === workingF) rep += repGain
              if (hold && o.faction === hold.faction) rep = Math.max(rep, hold.repTarget)
              return rep !== o.factionRep ? { ...o, factionRep: rep } : o
            }),
            money: ns.getServerMoneyAvailable('home') + moneyGain,
            r: BASE_PRICE_MULT,
            nodeMoneyMult: 1,
            owned: [...installedCount.keys()],
            soaOwned: [...allCount.keys()].filter(isSoa).length,
            channelWeights,
            channels: channelsUsed,
          })
          if (f && f.M > 1)
            futures.push({
              waitMs,
              M: heldM * f.M,
              ...(repGain > 0 ? { repProjected: Math.round(repGain) } : {}),
              ...(hold ? { holdFor: hold.faction, holdRepTarget: Math.round(hold.repTarget) } : {}),
              moneyProjected: Math.round(moneyGain),
            })
        } catch {
          /* a projection that cannot be priced is simply not offered */
        }
      }

      incomeCalibration = scoreIncome(prevIncome, incomePerSec)

      // CALIBRATE THE FUTURES BEFORE ACTING ON THEM.
      //
      // Everything below this line weighs "install now" against "install after
      // waiting", and the wait side is a projection. Score what the last pass
      // promised against what actually arrived, then shrink the new
      // projections by the measured delivery. trust === null (nothing has come
      // due yet) leaves them untouched and says so, rather than inventing a
      // figure. See scoreFutures() in installgate.js for the live failure this
      // exists to stop: 20.78 hours, zero installs, on a promised M that was
      // never once reached.
      futuresCalibration = scoreFutures(prevFutures, M, Date.now(), prevCalSamples)
      // Record the UNDISCOUNTED projections — the claim being audited is what
      // the model predicted, not what we chose to believe of it.
      // Carry unmatured projections forward and add this pass's own, so a
      // 15-minute horizon actually survives the ~5-minute pass cadence. The
      // logic is in installgate.js so it is testable ([IG14]); inline here it
      // overwrote the list every pass and nothing ever came due.
      futurePredictions = carryPredictions(prevFutures, futures, M, Date.now())
      futures = discountFutures(futures, M, futuresCalibration?.trust)
    }

    const gate = shouldInstall({
      ageMs: Date.now() - (info?.lastAugReset ?? 0),
      M,
      queued: total,
      // THE EXIT. The Red Pill appearing in the plan (or already sitting in
      // the queue from a partially executed one) makes this the install that
      // ends the node, and installgate.js must not weigh it on the multiplier
      // channels it deliberately has none of. Read from the plan rather than
      // from a flag we set ourselves, so it is true exactly when the purchase
      // is real.
      terminal: (plan?.buy ?? []).some((b) => b.name === 'The Red Pill') || pending.includes('The Red Pill'),
      // THE COUNT GATE, reported from the plan itself rather than assumed.
      //
      // countShort  how many distinct augmentations the exit still needs.
      // countGain   how many this install would actually add — NeuroFlux is
      //             excluded because it is the one repeatable augmentation and
      //             contributes nothing to a DISTINCT count, ever, which is the
      //             whole mechanism behind the treadmill.
      // countReachableLater  is any distinct augmentation still obtainable by
      //             WAITING? Read from `plan.skipped`, which names every
      //             augmentation the planner held back and why. This is the
      //             escape that keeps the hold from becoming a deadlock: when
      //             nothing is reachable, waiting cannot help and the rate rule
      //             is left alone.
      // WHICH EXIT GATE BINDS — objective.js owns the model, this supplies the
      // three facts it needs. `exitLevelReached` is the live level against the
      // node's own exit requirement, not a forecast: the run has demonstrated
      // it can get there, repeatedly, which is what makes further multiplier
      // worthless and further money essential.
      binding: bindingGate({
        // THE SIMULATION. Prices "install k more times, then finish" for every
        // k and hands bindingGate the winner, so the install-vs-hold trade is
        // decided by comparing trajectories rather than by a threshold on the
        // current hacking level. Refuses (and bindingGate falls back to the
        // threshold, loudly) whenever a rate is missing.
        exitPolicy: (() => {
          try {
            const cyc = cycleStats(JSON.parse(ns.read('/tel/lifetimes.txt') || '[]'), info?.currentNode)
            const rp = (offers ?? []).find((a) => a.name === TERMINAL_AUG)
            const d = bitNodeMults(info?.currentNode)?.WorldDaemonDifficulty
            return bestExitPolicy({
              money: player.money ?? 0,
              incomePerSec: incomePerSec + contractMoneyPerSec,
              hacking: player.skills?.hacking,
              hackingExp: player.exp?.hacking ?? 0,
              hackingMult: player.mults?.hacking,
              expPerSec: schedule?.expPerSec,
              repPerSec: schedule?.estimated ? null : schedule?.measuredBaseRepPerSec,
              exitRep: rp?.factionRep ?? 0,
              exitFavor: rp?.favor ?? 0,
              cycleHours: cyc?.cycleHours,
              multGainPerCycle: cyc?.multGainPerCycle,
              exitLevel: typeof d === 'number' && isFinite(d) && d > 0 ? WD_BASE_HACKING * d : null,
              // The requirement, not the shortfall: exitHours skips the leg
              // itself when the cash is already there, and feeding it a claim
              // that had collapsed to 0 would hide the leg entirely.
              joinMoney: exitFactionMoneyReq(candidates) ?? 0,
              terminalRep: rp?.baseRep ?? 0,
              donationCost: typeof rp?.donationCost === 'number' ? rp.donationCost : null,
              // 150 x FavorToDonateToFaction (Faction/formulas/donation.ts:17),
              // read from the node rather than assumed.
              favorToDonate: (() => {
                const f = bitNodeMults(info?.currentNode)?.FavorToDonateToFaction
                return typeof f === 'number' && isFinite(f) && f > 0 ? 150 * f : null
              })(),
            })
          } catch {
            return null
          }
        })(),
        // Membership, not affordability. See bindingGate: the money gate must
        // stay bound until we are actually a member, or holding the money ends
        // the gate and frees the install that destroys it.
        exitFactionJoined: Array.isArray(player?.factions) ? player.factions.includes(EXIT_FACTION) : null,
        exitFactionMoneyReq: exitFactionMoneyReq(candidates),
        countShort: ticketsWanted,
        joinMoneyShort: (() => {
          const c = joinMoneyClaim(candidates, player)
          return typeof c === 'number' ? c : 0
        })(),
        // What acquiring the terminal augmentation still costs. Priced off the
        // live offer — base price plus the donation its reputation wall
        // converts to past 150 favour — so it needs no constant and follows the
        // faction_rep multiplier automatically. Zero once it is owned, already
        // affordable, or not on offer (not a member yet, which the join claim
        // above is already holding for).
        terminalShort: (() => {
          const rp = (offers ?? []).find((a) => a.name === TERMINAL_AUG)
          if (!rp) return 0
          const cost = (rp.baseCost ?? 0) + (typeof rp.donationCost === 'number' && isFinite(rp.donationCost) ? rp.donationCost : 0)
          const have = player.money ?? 0
          return cost > have ? cost : 0
        })(),
        exitLevelReached: (() => {
          const d = bitNodeMults(info?.currentNode)?.WorldDaemonDifficulty
          if (!(typeof d === 'number' && isFinite(d) && d > 0)) return false
          return (player.skills?.hacking ?? 0) >= WD_BASE_HACKING * d
        })(),
      }),
      countShort: ticketsWanted,
      countGain: (() => {
        const seen = new Set(installedCount.keys())
        let n = 0
        for (const b of [...(plan?.buy ?? []), ...pending.map((p) => ({ name: p }))]) {
          if (b.name === NFG || seen.has(b.name)) continue
          seen.add(b.name)
          n++
        }
        return n
      })(),
      countReachableLater: (plan?.skipped ?? []).some((sk) => sk?.name && sk.name !== NFG && !installedCount.has(sk.name)),
      // RHO: the rate a completed life actually sustains in THIS BitNode, which
      // is what the stopping rule compares the marginal gain against. Measured
      // from the lifetimes ledger, same node only, null until two lives have
      // finished here — installgate.js falls back and says so rather than
      // running on a number nobody measured.
      ...(() => {
        try {
          const r = achievableRate(JSON.parse(ns.read('/tel/lifetimes.txt') || '[]'), info?.currentNode)
          return r ? { rho: r.rate, rhoMeta: `median of ${r.n} completed BitNode ${info?.currentNode} life/lives` } : {}
        } catch {
          return {}
        }
      })(),
      // THE EXIT LEVEL OF THIS NODE, not of the one this file was written in.
      // The gate's experience floor and the terminal sprint both price hours
      // against it, so a BitNode 1 run left on the 9000 default would believe
      // it needs three times the level it does and would keep installing where
      // sprinting already wins. Unknown node reads null and the argument goes
      // undefined, which leaves installgate.js's documented default standing
      // rather than inventing a number.
      target: (() => {
        const d = bitNodeMults(info?.currentNode)?.WorldDaemonDifficulty
        return typeof d === 'number' && isFinite(d) && d > 0 ? WD_BASE_HACKING * d : undefined
      })(),
      // The experience term (installgate.js) needs live experience, not the
      // level — level is already the multiplier times the log of this, so
      // feeding the level back would double-count the quantity being weighed.
      exp: player.exp?.hacking ?? 0,
      // The IPvGO reputation bonus, which the install DESTROYS
      // (Go/Go.ts:34-47 zeroes nodePower). go.js publishes it; ns.read is 0GB.
      // Absent or unreadable reads as 0, which UNDER-states the cost and so
      // biases toward installing — the wrong direction. It is tolerable only
      // because go.js is supervised and its absence is itself an alarm; if Go
      // ever stops being part of the stack this should become a blocking read.
      goBonusPct: goBonus(ns),
      // FAVOUR GAINED BY INSTALLING. Reputation banked this life converts to
      // favour (favor.ts:22), favour is permanent, and it multiplies all future
      // faction work by 1 + favor/100 (reputation.ts:9). So the install buys a
      // real, lasting multiplier on the reputation channel that M alone does
      // not contain — the exact mirror of the Go bonus, which does NOT count
      // because it regrows.
      //
      // Measured for the faction the schedule intends to work NEXT, since that
      // is whose rate the gain will actually accelerate.
      favorGain: favorGainOf(sing, schedule?.current?.faction, canJoin, {
        // Only a MEASURED rate is passed. When the schedule could not measure
        // one it falls back to a placeholder 1 rep/s, and feeding that in would
        // make every dollar of income look like a colossal reputation rate —
        // the unlock would price as enormous on exactly the passes where we
        // know least. `estimated` is the schedule's own flag for that.
        baseRepPerSec: schedule?.estimated ? null : schedule?.measuredBaseRepPerSec,
        incomePerSec,
        repMult: player.mults?.faction_rep,
      }),
      prev,
      futures,
      incomePerSec,
      incomeSource,
    })

    // ------------------------------------------------------------------
    // THE TERMINAL SPRINT. Once The Red Pill is INSTALLED, the run ends at
    // hacking `gate.target` (9000 here), and the question changes shape:
    // keep installing (each install resets the exp climb but compounds the
    // multiplier) or FREEZE and grind exp to the target in this life. Both
    // paths are already priced — the sprint is expForSkill at the current
    // multiplier over the measured exp flow; the install path is joinplan's
    // windowed level ladder, the same arithmetic that prices every other
    // level target. Sprint wins when its hours are shorter; when it does,
    // the install is SUPPRESSED and the final life is announced.
    //
    // The last step is deliberately human: backdooring w0r1d_d43m0n destroys
    // the BitNode, cmd.js refuses `wd` by design, and this block only ever
    // SURFACES readiness — it must never path to or execute that backdoor
    // (which is also why w0r1d_d43m0n stays OUT of STORY_SERVERS: backdoor.js
    // would faithfully end the node on its next pass).
    // ------------------------------------------------------------------
    let terminal = null
    if (installedCount.has('The Red Pill')) {
      const expNeed = expForSkill(gate.target, player.mults?.hacking ?? 1)
      const expRate = schedule?.expPerSec
      const sprintH = expRate > 0 ? Math.max(0, expNeed - (player.exp?.hacking ?? 0)) / expRate / 3600 : null
      const ladderH = joinState ? timeToMeet({ type: 'skills', skills: { hacking: gate.target } }, { ...joinState, expPerSec: schedule?.expPerSec }) : null
      const sprint = sprintH !== null && isFinite(sprintH) && (ladderH === null || sprintH <= ladderH)
      terminal = {
        redPill: true,
        target: gate.target,
        sprintH: sprintH !== null ? Math.round(sprintH * 100) / 100 : null,
        installLadderH: ladderH !== null ? Math.round(ladderH * 100) / 100 : null,
        sprint,
      }
      try {
        // The server exists only after the Red Pill installs; absent = not yet.
        const wdReq = ns.getServerRequiredHackingLevel('w0r1d_d43m0n')
        if ((player.skills?.hacking ?? 0) >= wdReq) {
          todo.push(`W0R1D_D43M0N IS READY: hacking ${player.skills.hacking} >= ${wdReq}. Run findpath.js w0r1d_d43m0n, connect, and backdoor it YOURSELF — cmd.js refuses wd by design, ending the BitNode is your click.`)
        } else {
          todo.push(`Red Pill installed — hacking ${player.skills?.hacking} of ${wdReq} for the final backdoor (${terminal.sprint ? `sprinting, ~${terminal.sprintH}h` : `installing toward it, ~${terminal.installLadderH}h`}).`)
        }
      } catch {
        /* server not spawned yet — the Red Pill install has not landed */
      }
    }

    // Persist BEFORE acting. An install never returns, so a write afterwards
    // would never happen and the next life would start with no history — and
    // the lastAugReset stamp is what stops that stale sample being reused.
    // The plan goes in the file too: "what would we have bought, and what was
    // one faction errand away" is the question this file is asked after the
    // fact, and it cannot be reconstructed from the save.
    ns.write(
      GATE,
      JSON.stringify(
        {
          at: new Date().toISOString(),
          lastAugReset: info?.lastAugReset,
          // Symmetric with the empty-queue write below: `planned` is always
          // present, so a reader never has to infer it from the shape.
          planned: true,
          joinClaim: joinMoneyClaim(candidates, player),
          pending,
          heldM,
          // The income model's inputs, persisted so the NEXT pass can score
          // this pass's prediction — and the score of the last one, published
          // whether it flatters the model or not.
          incomeSample: makeIncomeSample(incomePerSec, player, schedule),
          incomeCalibration,
          futuresCalibration,
          futurePredictions,
          // The objective the plan was priced under — derived per pass from
          // measured elasticities, or 'flat' when derivation refused. A
          // weight jump between passes is visible here, not silent.
          objective: weightsMeta,
          // WHAT THE BUDGET MUST ACTUALLY HOLD: the plan's cost NET of what
          // income will deliver before the install happens anyway. Money is
          // only needed AT the install; holding the gross figure starved the
          // fleet to zero servers against a plan income would have covered
          // within a window. Half the remaining window is the deliberately
          // conservative horizon — the gate can fire early, and an over-hold
          // costs minutes of fleet compounding while an under-hold costs an
          // augmentation. Unreadable income keeps the gross hold.
          budgetClaim:
            plan && incomePerSec > 0 && joinState?.windowH > 0
              ? Math.max(
                  0,
                  plan.totalCost -
                    // The horizon is TIME-TO-INSTALL, and when the gate is
                    // holding it has already named that time: bestWait is the
                    // winning future's wait. Half of the larger of {remaining
                    // median window, the gate's own chosen wait}, floored at
                    // 15 minutes — because a life that has outrun the window
                    // is holding on purpose, still earning, and zeroing the
                    // discount there restored the full gross hold at exactly
                    // the moment more income was guaranteed. Money is only
                    // needed AT the install; every dollar held before then is
                    // fleet compounding forgone.
                    incomePerSec *
                      Math.max(
                        (joinState.windowH - (joinState.lifeAgeH ?? 0)) / 2,
                        (gate?.bestWait > 0 ? gate.bestWait / 3600000 : 0) / 2,
                        0.25,
                      ) *
                      3600,
                )
              : plan
                ? plan.totalCost
                : 0,
          // The futures the gate weighed, hold candidates included — the
          // rule's inputs, not just its verdict. bestWait names the winner;
          // without this list a hold that lost (or won) is invisible, and an
          // invisible decision cannot be checked. Found the hard way: a
          // 30-minute telemetry watch for hold candidates timed out because
          // this array was consumed but never published.
          futures,
          plannedM: plan ? plan.M : 1,
          plan: plan ? { buy: plan.buy, totalCost: plan.totalCost, exact: plan.exact, stats: plan.stats, skipped: plan.skipped.slice(0, 20) } : null,
          ...gate,
        },
        null,
        2,
      ),
      'w',
    )

    // Only meaningful when there is actually something to install: an override
    // that fires on an empty plan would call installAugmentations for nothing
    // and reset the life for zero gain.
    const forcedInstall = flags['install-now'] && (pending.length > 0 || (plan?.buy?.length ?? 0) > 0)

    if (!canInstall || flags['no-install'] || flags.dry) {
      todo.push(`${pending.length} queued + ${plan ? plan.buy.length : 0} planned (M=${M.toFixed(4)}) — ${gate.why}`)
    } else if (gate.install && terminal?.sprint) {
      // THE FINAL LIFE. Installing would reset the exp climb the sprint is
      // made of; the ladder says more installs reach the target SLOWER than
      // this life's grind. Hold every install until the backdoor is yours.
      did.push(
        `FINAL LIFE: The Red Pill is installed and sprinting to hacking ${terminal.target} takes ~${terminal.sprintH}h this life vs ~${terminal.installLadderH ?? '?'}h through more installs — installs SUPPRESSED.`,
      )
    } else if (gate.install || forcedInstall) {
      if (forcedInstall && !gate.install) {
        did.push(`INSTALL FORCED by --install-now. The gate would have held: ${gate.why}`)
      }
      // EXECUTE THE PLAN, IN ORDER, RE-PRICING AS WE GO.
      //
      // A plan is computed from a snapshot and money moves between the snapshot
      // and the spend. Buying blind against a stale price is the "plan that
      // cannot be executed, discovered by failing" shape in CLAUDE.md's table —
      // planBatch's 7,274 placement failures reporting health: stalled. So each
      // purchase re-reads the price the game will actually charge and stops if
      // it has drifted, rather than silently buying something else at a rank the
      // plan never priced.
      const bought = []
      if (plan) {
        for (const item of plan.buy) {
          const live = sing.getAugmentationPrice(item.name)
          // COMPARE AUG-PRICE TO AUG-PRICE. item.price carries the donation
          // for rep-walled purchases (augplan folds it into the row so the
          // budget binds on the true total) — but getAugmentationPrice knows
          // nothing of donations, so comparing the blended figure against it
          // reported "98.6% drift" on every donation aug and ABORTED the
          // whole plan at item one. Live cost: six top-tier augmentations
          // (M = 12.78) planned and never bought across five installs, the
          // aug count frozen at 19, while the gate believed each install was
          // banking ln(12.78). The donation part is re-derived from the LIVE
          // shortfall at execution anyway, so it needs no staleness check of
          // its own here.
          const plannedAugPrice = item.price - (item.donation ?? 0)
          const drift = Math.abs(live - plannedAugPrice) / Math.max(plannedAugPrice, 1)
          if (drift > 0.01) {
            did.push(`STOPPED executing the plan at ${item.name}: planned $${plannedAugPrice.toFixed(0)} (aug part), game says $${live.toFixed(0)} (${(drift * 100).toFixed(1)}% drift) — the plan is stale`)
            break
          }
          // The affordability check covers the WHOLE step: the donation is
          // paid right before the purchase, from the same balance.
          const stepCost = live + (item.donation ?? 0)
          if (ns.getServerMoneyAvailable('home') < stepCost) {
            did.push(`STOPPED executing the plan at ${item.name}: $${stepCost.toFixed(0)} needed (incl. donation), $${ns.getServerMoneyAvailable('home').toFixed(0)} held — the plan over-spent`)
            break
          }
          if (item.donation > 0) {
            // The plan priced the donation conservatively (full shortfall per
            // item); donate only what is STILL short at execution time — an
            // earlier donation for a same-faction item may already cover it.
            const short = item.donation && sing.getAugmentationRepReq(item.name) - sing.getFactionRep(item.faction)
            if (short > 0) {
              const fwrgExec = bitNodeMults(info?.currentNode)?.FactionWorkRepGain ?? 1
              const dollars = Math.ceil(donationForRep(short, player.mults?.faction_rep ?? 1, fwrgExec) * 1.01)
              if (!sing.donateToFaction(item.faction, dollars)) {
                did.push(`DONATION REFUSED: $${ns.format.number(dollars)} to ${item.faction} for ${item.name} — favour or funds short at execution`)
                break
              }
              did.push(`donated $${ns.format.number(dollars)} to ${item.faction} (${Math.round(short).toLocaleString()} rep) for ${item.name}`)
            }
          }
          if (!sing.purchaseAugmentation(item.faction, item.name)) {
            // The shipped file ignored this return value entirely, which is how
            // a prerequisite failure stayed invisible.
            did.push(`REFUSED by the game: ${item.name} from ${item.faction} — rep, money or an unmet prerequisite`)
            break
          }
          bought.push(item.name)
        }
      }
      const installing = pending.length + bought.length
      ns.write(STATUS, JSON.stringify({ at: new Date().toISOString(), did, bought, installing, gate }, null, 2), 'w')
      did.push(`bought ${bought.length} of ${plan ? plan.buy.length : 0} planned; installing ${installing} augmentation(s) — ${gate.why}`)
      if (installing === 0) {
        // Nothing to install and nothing bought: do NOT call installAugmentations,
        // which would prestige for no gain. Say so instead.
        todo.push('the gate fired but no augmentation could be bought — check /tel/installgate.txt for the plan and why each purchase was refused')
      } else {
        // The LIFETIMES LEDGER — the install window and the multiplier growth
        // are the two measured inputs the rep ladder (favor.js) prices from,
        // and this is the only moment both are knowable: the life is ending
        // and its multiplier is final. /tel files survive installs, so the
        // ledger accumulates across lives; last 20 kept.
        try {
          const ledger = JSON.parse(ns.read('/tel/lifetimes.txt') || '[]')
          // scorecard.installRecord: this life's realized figures, predictions
          // for the NEXT entry made from the numbers the schedule actually
          // priced with this pass, and scores of the PREVIOUS entry's
          // predictions — the forecast layer grading itself at the only
          // moment the truth is knowable.
          ledger.push(
            installRecord(
              ledger[ledger.length - 1] ?? null,
              {
                at: new Date().toISOString(),
                lifeH: Math.round(((Date.now() - (info?.lastAugReset ?? Date.now())) / 3600000) * 100) / 100,
                hackMult: player.mults?.hacking,
                // THE REWARD THIS LIFE CASHED IN, and the node it was earned in
                // — the two fields scorecard.achievableRate needs to compute
                // rho. `lnM` is ln(Meff), the SAME quantity the stopping rule
                // compares against, so the rate is dimensionally the rule's own
                // and not a near-relative of it. `hackMult` above is the raw
                // hacking channel and would understate a weighted basket, which
                // would understate rho, which would hold installs too long —
                // the exact bias being fixed here.
                bitNode: info?.currentNode,
                lnM: gate?.Meff > 1 ? Math.log(gate.Meff) : undefined,
                // FAVOUR AT THE EXIT FACTION — the quantity the favour ladder
                // actually advances, and the one this ledger did not record.
                //
                // Late in a node, installs stop adding augmentations and start
                // converting banked reputation into permanent favour, so a life
                // reads `augs 31, lnM 0.2` and looks identical to the NeuroFlux
                // treadmill that had to be fixed this morning. It is the
                // opposite: it is the ladder to 150 favour, where money can be
                // donated for the 2.5m reputation The Red Pill needs instead of
                // ground out. Five such lives were misread as a stall by a
                // human reading this file, because the progress was invisible
                // in it.
                exitFavor: (() => {
                  try {
                    return canJoin ? sing.getFactionFavor('Daedalus') : undefined
                  } catch {
                    return undefined
                  }
                })(),
                // Distinct augmentations INCLUDING what this install lands —
                // the count trajectory behind Daedalus's 30-aug forecast.
                augs: allCount.size,
              },
              { g: joinState?.rateGrowthPerCycle, windowH: joinState?.windowH, augsPerWindow: joinState?.augsPerWindow },
            ),
          )
          ns.write('/tel/lifetimes.txt', JSON.stringify(ledger.slice(-20)), 'w')
        } catch {
          /* an unreadable ledger must not block the install — it only costs one sample */
        }
        // SPEND THE REMAINDER FIRST. `prestigeHomeComputer`
        // (Server/ServerHelpers.ts:226-239) resets programs, serversOnNetwork
        // and ramUsed but touches NEITHER maxRam NOR cpuCores, so home RAM and
        // cores are permanent for the whole BitNode — while money resets to
        // $1,262 (PlayerObjectGeneralMethods.ts:102). Every dollar still held
        // when installAugmentations is called is therefore DESTROYED.
        //
        // CLAUDE.md has said "run homeup.js --reserve 0 before installing, this
        // is not optional" since the life that installed holding $2.07
        // QUADRILLION. It said it to a HUMAN. Nothing on the autonomous path
        // ever did it, so the loop has been burning its remainder on every
        // install it has ever made — the same shape as every other gap this
        // session: a step that works while someone is driving and silently
        // does not when nobody is.
        //
        // Bounded, and never allowed to block the install. homeup takes the
        // global UI lock and walks to Alpha Enterprises, so it can legitimately
        // fail to start or fail to finish; an install deferred forever because
        // a spender would not exit is far worse than a burnt remainder. On
        // timeout we install anyway and say what happened.
        try {
          const pid = ns.exec('homeup.js', 'home', 1, '--reserve', 0)
          if (pid) {
            const until = Date.now() + 30000
            while (ns.isRunning(pid) && Date.now() < until) await ns.sleep(500)
            did.push(
              ns.isRunning(pid)
                ? 'pre-install spend-down did not finish within 30s — installing anyway, the remainder is forfeit'
                : 'spent the remainder on home RAM/cores before installing (money does not survive a prestige; home RAM does)',
            )
          } else {
            did.push('could not start homeup.js to spend the remainder — installing anyway, the remainder is forfeit')
          }
        } catch (e) {
          did.push(`pre-install spend-down failed (${String(e).slice(0, 60)}) — installing anyway`)
        }
        ns.write(STATUS, JSON.stringify({ at: new Date().toISOString(), did, bought, installing, gate }, null, 2), 'w')
        sing.installAugmentations('boot.js')
        return // the game reloads; boot.js brings the stack back up
      }
    } else {
      // Holding is a decision, not silence: published every pass with the
      // numbers behind it, so a gate that is stuck can be told from one that is
      // correctly waiting.
      did.push(gate.why)
      if (plan && plan.skipped.length) {
        const near = plan.skipped.filter((s) => s.why === 'reputation').sort((a, b) => a.short - b.short)[0]
        if (near) todo.push(`${Math.round(near.short).toLocaleString()} more ${near.faction} reputation unlocks ${near.name}`)
      }
    }
  }

  const report = { at: new Date().toISOString(), capabilities: { canJoin, canWork, canBuyAug, canInstall }, did, todo, contracts: contractForecast, stocks: stockForecast, slot: crimeAlt ?? null }
  ns.write(STATUS, JSON.stringify(report, null, 2), 'w')
  ns.write(TODO, JSON.stringify({ at: report.at, todo }, null, 2), 'w')

  for (const d of did) ns.tprint(`progress: ${d}`)
  for (const t of todo) ns.tprint(`progress: TODO ${t}`)
  if (!did.length && !todo.length) ns.tprint('progress: nothing to do')
}
